  "{0}: “Bu kür seni {1} dövüş boyunca canavara çevirir. Testlerde çıkmaz… genelde.” Fiyatı {2}.\n\nKabul edersen vuruş, kondisyon, hız ve çene ciddi artar. Yakalanırsan 6 ay ile 2 yıl arası men, popülerlik kaybı ve sponsor iptali.": "{0}: “Siklus ini akan mengubahmu jadi monster selama {1} pertarungan. Tidak akan terdeteksi tes… biasanya.” Harganya {2}.\n\nJika kamu terima, striking, kardio, kecepatan, dan dagumu naik drastis. Jika tertangkap: larangan 6 bulan hingga 2 tahun, popularitas hilang, dan sponsor dibatalkan.",
  "Kabul et": "Terima",
  "Federasyona ihbar et": "Laporkan ke komisi",
  "Kürü aldın. Aynada başka biri var. Sonraki {0} dövüşte çok güçlüsün… ama her dövüşten sonra test riski var.": "Kamu mengambil siklus itu. Ada orang lain di cermin. Kamu sangat kuat untuk {0} pertarungan ke depan… tapi setiap laga membawa risiko tes.",
  "Kibarca reddettin. Temiz bir kariyer, huzurlu bir uyku.": "Kamu menolak dengan sopan. Karier bersih, tidur nyenyak.",
  "Federasyona ihbar ettin. Basın seni “temiz sporun sesi” ilan etti. Popülerlik +2.": "Kamu melaporkannya ke komisi. Pers menyebutmu “suara olahraga bersih”. Popularitas +2.",
  "💼 Sponsorluk Teklifi": "💼 Tawaran Sponsor",
  "Bahis": "Taruhan",
  "\n\nAma bir bahis şirketi… Bazı taraftarların hoşuna gitmeyebilir.": "\n\nTapi ini perusahaan taruhan… Sebagian penggemar mungkin tidak suka.",
  "{0} seninle çalışmak istiyor. Şortunda logoları olacak, karşılığında {1} ödeyecekler.{2}": "{0} ingin bekerja sama denganmu. Logo mereka akan ada di celanamu, dan mereka akan membayarmu {1}.{2}",
  "Pazarlık yap (+%50 dene)": "Negosiasi (coba +50%)",
  " (Bazı taraftarlar tepkili: popülerlik -2)": " (Sebagian penggemar kecewa: popularitas -2)",
  "{0} ile anlaştın. +{1}{2}": "Kamu tanda tangan dengan {0}. +{1}{2}",
  "Sıkı pazarlık işe yaradı! +{0}": "Tawar-menawar keras membuahkan hasil! +{0}",
  "{0} masadan kalktı. \"Başka dövüşçüler de var.\"": "{0} pergi. \"Masih ada petarung lain.\"",
  "Teklifi reddettin. İmajın temiz kaldı.": "Kamu menolak tawaran itu. Citramu tetap bersih.",
  "Antrenmanda sparring partnerini uyuttuğun bir video 2 milyon izlendi. Yorumlar ikiye bölünmüş durumda. Ne paylaşırsın?": "Video kamu meng-KO partner sparring-mu ditonton 2 juta kali. Komentarnya terbelah. Apa yang kamu posting?",
  "Sıklettekilere laf at": "Tantang seluruh divisi",
  "Mütevazı bir teşekkür yaz": "Tulis ucapan terima kasih yang rendah hati",
  "Görmezden gel": "Abaikan",
