  "Sabah 5’te koşu, öğlen spar, akşam grappling. {rakip}, ben hazırım. #Kamp": "Lari jam 5 pagi, sparring siang, grappling malam. {rakip}, aku siap. #Kamp",
  "{hoca} bugün beni yere serdi. Kafeste kimse bunu yapamayacak. 😤": "{hoca} menjatuhkanku hari ini. Tak ada yang bisa melakukannya di kandang. 😤",
