  "{rakip}, sosyal medyada çok cesursun. Kafeste görüşürüz.": "{rakip}, kamu sangat berani di media sosial. Sampai jumpa di kandang.",
  "Bu gece {rakip} uyumayacak. Çünkü maç gecesi uyutacağım. 💤": "{rakip} tak akan tidur malam ini. Karena aku akan menidurkannya di malam pertarungan. 💤",
  "{rakip} diye bir dövüşçü yok, sadece bir sonraki kurbanım var.": "Tak ada petarung bernama {rakip}, hanya korban berikutnya.",
