  "{rakip}’in çenesi o kadar dayanıklı değil, herkes biliyor.": "Dagu {rakip} tidak sekuat itu, semua orang tahu.",
  "Kamera önünde herkes aslan. Kafes kapısı kapanınca görürüz {rakip}.": "Semua jadi singa di depan kamera. Kita lihat saat pintu kandang tertutup, {rakip}.",
