  "Salonumuza yeni bir savaşçı katıldı: {0}. {1} bu ismi yakında çok duyacak! 🥊": "Seorang pejuang baru bergabung dengan sasana kami: {0}. {1} akan sering mendengar nama ini sebentar lagi! 🥊",
  "KULİS: {org} yönetimi {a} ile {b} maçını ayarlamak üzere. Tarih belli değil.": "ORANG DALAM: Manajemen {org} akan mempertemukan {a} vs {b}. Belum ada tanggal.",
