  "KULİS: {a} ve {b} arasında salon kavgası iddiası! Görgü tanıkları konuşuyor.": "ORANG DALAM: Kabar perkelahian di sasana antara {a} dan {b}! Para saksi angkat bicara.",
  "KULİS: {c} kemeri boşaltmayı düşünüyor mu? Yakın çevresi sessiz.": "ORANG DALAM: Apakah {c} berpikir melepas sabuk? Lingkaran dekatnya bungkam.",
  "KULİS: {p} ile ilgilenen bir film yapımcısı olduğu söyleniyor. 🎬": "ORANG DALAM: Seorang produser film dikabarkan tertarik pada {p}. 🎬",
  "KULİS: {a} doping testinden geçemedi mi? Resmi açıklama bekleniyor.": "ORANG DALAM: Apakah {a} gagal tes doping? Pernyataan resmi ditunggu.",
  "KULİS: {b} emekliliği düşünüyor. Son maçını memleketinde yapmak istiyor.": "ORANG DALAM: {b} mempertimbangkan pensiun. Ingin laga terakhir di kampung halaman.",
  "ANKET: {a} vs {p} olsa kim kazanır? 🗳️ {a} %{x} · {p} %{y}": "POLLING: {a} vs {p}, siapa menang? 🗳️ {a} {x}% · {p} {y}%",
  "ANKET: Sıkletin en iyi vuruşçusu kim? 🗳️ {a} %{x} · {p} %{y}": "POLLING: Striker terbaik di divisi? 🗳️ {a} {x}% · {p} {y}%",
  "ANKET: {c} kemeri daha kaç maç tutar? 🗳️ 1-2 maç %{x} · 3+ maç %{y}": "POLLING: Berapa laga lagi {c} memegang sabuk? 🗳️ 1-2 laga {x}% · 3+ laga {y}%",
  "ANKET: Yılın nakavtı kimin? 🗳️ {p} %{y} · {b} %{x}": "POLLING: KO terbaik tahun ini milik siapa? 🗳️ {p} {y}% · {b} {x}%",
  "ANKET: {p} ayakta mı daha tehlikeli, yerde mi? 🗳️ Ayakta %{x} · Yerde %{y}": "POLLING: {p} lebih berbahaya saat berdiri atau di bawah? 🗳️ Berdiri {x}% · Bawah {y}%",
  "ANKET: {a} trash talk’ta haklı mı? 🗳️ Evet %{x} · Hayır %{y}": "POLLING: Apakah {a} benar dalam trash talk-nya? 🗳️ Ya {x}% · Tidak {y}%",
  "ANKET: Sıklette bir sonraki şampiyon kim olur? 🗳️ {p} %{y} · {b} %{x}": "POLLING: Siapa juara berikutnya di divisi? 🗳️ {p} {y}% · {b} {x}%",
  "ANKET: {org} en iyi maçı hangisiydi? 🗳️ {a} vs {b} %{x} · {p} maçı %{y}": "POLLING: Apa pertarungan {org} terbaik? 🗳️ {a} vs {b} {x}% · laga {p} {y}%",
  "📊 ANALİZ: {p} son maçlarında {stat} istatistiğinde ciddi gelişme gösterdi. Sıklet dikkat!": "📊 ANALISIS: {p} menunjukkan peningkatan serius dalam {stat} di laga-laga terakhir. Divisi, perhatikan!",
  "📊 ANALİZ: {a} takedown savunması sıkletin en iyisi. Güreşçiler için kâbus.": "📊 ANALISIS: {a} punya pertahanan takedown terbaik di divisi. Mimpi buruk bagi pegulat.",
  "📊 ANALİZ: {c} şampiyonluğunu kaybetmesi için bir “stil” gerekiyor: sabırlı bir kontra dövüşçüsü.": "📊 ANALISIS: Untuk menggulingkan {c} butuh “gaya” tertentu: petarung serangan balik yang sabar.",
  "📊 ANALİZ: {p} popülerlik grafiği son 3 ayda dikey çıkışta.": "📊 ANALISIS: Grafik popularitas {p} melonjak vertikal dalam 3 bulan terakhir.",
  "📊 ANALİZ: {b} üçüncü rauntlarda düşüyor. Tempo onu yıkabilir.": "📊 ANALISIS: {b} melemah di ronde ketiga. Tempo bisa mematahkannya.",
  "📊 ANALİZ: {a} dakikada ortalama 5,2 isabetli vuruş atıyor. Sıklet rekoru.": "📊 ANALISIS: {a} mendaratkan rata-rata 5,2 pukulan signifikan per menit. Rekor divisi.",
  "📊 ANALİZ: {p} maçlarının yarısından fazlasını bitirişle kazandı. Hakemlere iş bırakmıyor.": "📊 ANALISIS: {p} memenangkan lebih dari separuh laganya lewat finish. Dia tak menyisakan pekerjaan untuk juri.",
  "📊 ANALİZ: {c} son beş maçta hiç yere düşmedi. Çenesi çelik gibi.": "📊 ANALISIS: {c} belum pernah dijatuhkan dalam lima laga. Dagu baja.",
  "📊 ANALİZ: {b} submission savunmasında zayıf. Grappler’lar sıraya girer.": "📊 ANALISIS: {b} lemah dalam pertahanan submission. Para grappler mengantre.",
  "📊 ANALİZ: {p} ile {a} eşleşmesi stil olarak sıkletin en ilginç maçı olur.": "📊 ANALISIS: {p} vs {a} akan jadi duel gaya paling menarik di divisi.",
  "Sabah 5’te koşu, öğlen sparring, akşam grappling. Tatil yok. 💪 #Kamp": "Lari jam 5 pagi, sparring siang, grappling malam. Tanpa hari libur. 💪 #Kamp",
