  "Karakterini Nasıl Kurarsın?": "Bagaimana Kamu Membangun Karaktermu?",
  "🌍 Uyruk: Antrenman imkânı başlangıç istatistiklerini, taraftar desteği başlangıç popülerliğini belirler. İlk salonun ve hocan da ülkene göre gelir.": "🌍 Kewarganegaraan: pilihan latihan menentukan statistik awal, dukungan penggemar menentukan popularitas awal. Sasana dan pelatih pertamamu juga tergantung negaramu.",
  "🎂 Yaş (18-30): Genç başlarsan ham ama hızlı gelişirsin (×1.3). Yaşlı başlarsan güçlü başlarsın ama 32’den sonra hız ve çene düşmeye başlar. 41’de emeklilik kaçınılmazdır.": "🎂 Usia (18-30): Mulai muda kamu mentah tapi berkembang cepat (×1,3). Mulai lebih tua kamu lebih kuat, tapi setelah 32 kecepatan dan dagu mulai menurun. Pensiun tak terhindarkan di usia 41.",
  "⚖️ Sıklet: Hafif sıkletler hızlı ve dayanıklıdır, ağır sıkletler sert vurur ama çabuk yorulur.": "⚖️ Kelas berat: Kelas ringan cepat dan tahan banting, kelas berat memukul keras tapi cepat lelah.",
  "🥋 Branş: En önemli seçim. Güçlü ve zayıf yönlerini, dolayısıyla nasıl dövüşeceğini belirler.": "🥋 Latar belakang: Pilihan paling penting. Menentukan kekuatan dan kelemahanmu, dan juga caramu bertarung.",
  "📖 Hikâye: Kendin yazabilir ya da oyuna yazdırabilirsin.": "📖 Kisah: Tulis sendiri atau biar game yang menuliskannya.",
  "🎲 Zar: Son adımda istatistiklerin zarla belirlenir. Beğenmezsen 2 kez yeniden atabilirsin.": "🎲 Dadu: Di langkah terakhir statistikmu diacak. Tidak suka? Kamu bisa mengacak ulang dua kali.",
  "Gelişim Puanı": "Poin Skill",
  "Kariyere 3 puanla başlarsın. Her antrenman kampı 1-3 puan verir (yoğunluk, yaş, kamp yeri, hoca ve kadro kalitesine bağlı). Kampın odak alanı ayrıca +1-3 gelişir.": "Kamu memulai karier dengan 3 poin. Setiap kamp latihan memberi 1-3 poin (tergantung intensitas, usia, lokasi kamp, kualitas pelatih dan staf). Area fokus kamp juga meningkat +1-3.",
  "Dövüşler de puan verir: galibiyet 2, bitiriş +1, bonus +1, kemer +1. Mağlubiyet ve beraberlik 1 puan.": "Pertarungan juga memberi poin: menang 2, finish +1, bonus +1, sabuk +1. Kalah dan seri 1 poin.",
  "📅 Bir dövüş döngüsü (kamp + toparlanma) yaklaşık 90-100 gün sürer. Yılda 3-4 kez dövüşürsün; her karar önemli.": "📅 Satu siklus laga (kamp + pemulihan) sekitar 90-100 hari. Kamu bertarung 3-4 kali setahun; setiap keputusan penting.",
  "Puanı istediğin istatistiğe harcarsın. 50’ye kadar +1 için 1 puan, 70’e kadar 2, 85’e kadar 3, sonrası 4 puan gerekir.": "Pakai poin untuk statistik apa pun. Sampai 50, +1 butuh 1 poin; sampai 70, 2; sampai 85, 3; setelahnya, 4 poin.",
  "Kamp sonunda tartıdan önce, dövüş sonrasında ya da Kariyer ekranındaki GELİŞİM sekmesinden harcayabilirsin.": "Kamu bisa memakainya sebelum timbang badan di akhir kamp, setelah laga, atau di tab PERKEMBANGAN di layar Karier.",
  "Nasıl Oynanır?": "Cara Bermain",
  "1️⃣ Rakip seç. Bölgesel aşamada sen seçersin, büyük organizasyonlarda rakibi organizasyon dayatır.": "1️⃣ Pilih lawan. Di tahap regional kamu yang memilih; di promosi besar lawan ditentukan.",
  "2️⃣ Kamp: odak alanı, oyun planı, yoğunluk, kilo verme ve basın toplantısı. Oyun planı rakibin zaafına denk gelirse kafeste büyük avantaj sağlar.": "2️⃣ Kamp: area fokus, rencana pertarungan, intensitas, penurunan berat badan, dan konferensi pers. Rencana yang mengincar kelemahan lawan memberi keunggulan besar di kandang.",
  "3️⃣ Dövüş: her raunt taktik seçersin. Kritik anlarda (rakip sarsıldı, submission yakalandı) hızlı karar verirsin.": "3️⃣ Laga: pilih taktik setiap ronde. Di momen kritis (lawan goyah, submission terkunci) kamu membuat keputusan cepat.",
  "4️⃣ Sonrası: bonuslar, röportaj, sıralama, kontrat teklifleri ve dövüşler arası olaylar.": "4️⃣ Setelahnya: bonus, wawancara, peringkat, tawaran kontrak, dan peristiwa di antara laga.",
  "🏆 Yol: Amatör → Bölgesel (CFC, Hexagon) → Büyük (PFC, ZEN, VIP) → DWCS veya kısa haber → UCC kemeri.": "🏆 Jalannya: Amatir → Regional (CFC, Hexagon) → Besar (PFC, ZEN, VIP) → DWCS atau mendadak → sabuk UCC.",
