  "Bir maçı hangi hareketle bitirirsen o hareket ustalık kazanır. Teknik çalışması ve spar da ustalık verir. Özel hareketler dövüş sırasında riskli ama görkemli fırsatlar açar. Gelişim puanın:": "Gerakan apa pun yang kamu pakai untuk mengakhiri laga akan bertambah penguasaannya. Latihan teknik dan sparring juga memberi penguasaan. Gerakan spesial membuka peluang berisiko tapi gemilang selama laga. Poin skill-mu:",
