  "{0} sokaklarından çıktı; {1} yaşında {2} galibiyete ulaştı, {3} bitiriş.": "Keluar dari jalanan {0}; {2} kemenangan dan {3} finish di usia {1}.",
  "HOCAN · {0}": "PELATIHMU · {0}",
  "ANLADIM": "MENGERTI",
  "İpuçlarını kapat": "Matikan tips",
  "Burası senin köşen": "Ini sudutmu",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. Aradaki haftalarda mağaza, sosyal medya ve gece hayatı seni bekliyor; ama unutma, her şeyin bir bedeli var.": "Uang, kesehatan, dan popularitasmu ada di atas. Saat siap, pilih lawan lewat “ATUR PERTARUNGAN”. Di minggu-minggu di antaranya, toko, media sosial, dan kehidupan malam menunggu; tapi ingat, semuanya ada harganya.",
  "Gelişim puanları": "Poin skill",
  "Kamplardan ve dövüşlerden puan kazanırsın, burada istatistiklerine dağıtırsın. 50’den sonra her artış pahalanır; zayıf yönünü kapatmak çoğu zaman daha akıllıcadır.": "Kamu mendapat poin dari kamp dan laga, lalu memakainya untuk statistik di sini. Di atas 50, setiap poin lebih mahal; menutup kelemahan biasanya langkah yang lebih cerdas.",
  "Rakibini seç": "Pilih lawanmu",
  "Her rakibin gücü ve zayıf yönü yazıyor. Kolay rakip güvenlidir ama az kazandırır; riskli bir rakibi yenersen sıralamada büyük bir sıçrama yaparsın.": "Kekuatan dan kelemahan setiap lawan tercantum. Lawan mudah itu aman tapi hasilnya kecil; kalahkan yang berisiko dan kamu melompat jauh di peringkat.",
  "Kamp başlıyor": "Kamp dimulai",
  "Önce kampın süresini seç. Uzun kamp daha çok geliştirir ama pahalıdır ve yorar. Kamptan önceki boş haftalarda teknik çalışabilir, spar yapabilirsin.": "Pertama pilih panjang kampmu. Kamp panjang mengembangkanmu lebih banyak tapi lebih mahal dan melelahkan. Di minggu bebas sebelum kamp kamu bisa melatih teknik dan sparring.",
  "Oyun planı": "Rencana pertarungan",
  "Rakibin zayıf yönüne uyan plan, dövüşte etkisini ikiye katlar. Keşif raporuna bak ve planını ona göre seç.": "Rencana yang cocok dengan kelemahan lawan menggandakan efeknya dalam laga. Cek laporan pengintaian dan pilih rencana sesuai itu.",
  "Burun buruna": "Berhadapan muka",
  "Tartıdan sonra rakibinle yüz yüze geleceksin. Takındığın tavır onun moralini bozabilir ya da sana pahalıya patlayabilir.": "Setelah timbang badan kamu akan berhadapan muka dengan lawan. Sikapmu bisa mematahkan semangatnya atau merugikanmu.",
  "Her raundun başında bir taktik seç, dövüş kendi akar. Rakip sarsıldığında ya da bir submission fırsatında hızlı karar vermen gerekir. Kondisyonunu izle: yorulursan her şey zorlaşır.": "Pilih taktik di awal setiap ronde dan laga mengalir dengan sendirinya. Saat lawan goyah atau submission terbuka, kamu harus memutuskan dengan cepat. Perhatikan kardiomu: begitu lelah, semuanya jadi lebih sulit.",
  "Dövüş bitti": "Laga selesai",
  "Mikrofon sende: röportajdaki sözlerin popülerliğini etkiler. Kazandığın puanları GELİŞİM sekmesinde harca. Güzel bir galibiyet mi? Paylaş, herkes görsün!": "Mikrofon milikmu: apa yang kamu katakan di wawancara memengaruhi popularitasmu. Pakai poin yang kamu dapat di tab PERKEMBANGAN. Kemenangan hebat? Bagikan agar semua orang melihat!",
