  "⚔️ {0} yine kazandı. Aranızdaki seri: {1}. Bu iş bitmedi.": "⚔️ {0} menang lagi. Rekor pertemuan kalian: {1}. Ini belum selesai.",
  "Söylemiştim. Kafeste ne zaman karşılaşsak aynı son. 😏": "Sudah kubilang. Setiap kita bertemu di kandang, akhirnya sama. 😏",
