  "🗡️ {0} kameralara konuştu: \"{1} yenilmez sanılıyor. O balonu ben patlatacağım.\" Yeni bir ezeli rakibin var.": "🗡️ {0} berkata ke kamera: \"Semua orang mengira {1} tak terkalahkan. Aku akan memecahkan gelembung itu.\" Kamu punya musuh bebuyutan baru.",
