  "İpucu: Hakarete espriyle, övünmeye sert, alaya soğukkanlı cevap ver.": "Tips: balas hinaan dengan humor, bualan dengan api, ejekan dengan es.",
  "{0} mi? Bu kafese değil, kreşe gitmeli.": "{0}? Anak ini tempatnya di penitipan anak, bukan di kandang.",
  "Şu surata bakın: daha önce çok dayak yediği belli.": "Lihat wajah itu. Kelihatan sudah sering dihajar.",
  "Onun antrenmanlarını izledim. Annem daha sert vuruyor.": "Aku menonton rekaman latihannya. Ibuku memukul lebih keras.",
  "Tek yeteneği basın toplantısında uyumamak.": "Satu-satunya bakat di sini adalah tetap terjaga di konferensi pers.",
  "Ben bu sıkletin kralıyım. Onu ilk rauntta uyutacağım, yazın bir kenara.": "Akulah raja divisi ini. Lampu padam di ronde satu, catat itu.",
  "Bana rakip bulamıyorlar, o yüzden bunu getirdiler.": "Mereka tak bisa mencarikanku lawan sungguhan, jadi mereka bawa yang ini.",
  "Kemeri şimdiden evime astım. Bu maç sadece formalite.": "Sabuknya sudah tergantung di rumahku. Laga ini cuma formalitas.",
