  "Hahaha! {0} titriyor bakın, ellerine bakın!": "Hahaha! {0} gemetar, lihat tangannya!",
  "Kilo verirken ağladığını duydum. Çok tatlı.": "Kudengar ada yang menangis saat menurunkan berat. Lucu sekali.",
