  "Hocası bile onun yerine utanıyor, şu hâline bakın.": "Bahkan pelatihnya malu. Lihat saja ini.",
  "Kreş mi? Doğru, cumartesi seni orada bebek gibi uyutacağım.": "Penitipan anak? Baik, Sabtu nanti kutidurkan kamu seperti bayi.",
  "Annenle antrenman yapıyorsan bana da numarasını ver, belki bir şey öğrenirim.": "Kalau kamu latihan dengan ibumu, minta nomornya. Mungkin aku bisa belajar sesuatu.",
  "Konuş, konuş. Cumartesi gecesi konuşamayacaksın.": "Terus saja bicara. Sabtu malam kamu tak akan bisa.",
  "Laflar ucuz. Kafeste görüşürüz.": "Omongan itu murah. Sampai jumpa di kandang.",
  "Bir daha ağzını açarsan burada dağıtırım seni!": "Buka mulutmu lagi dan kuhajar kamu di sini!",
  "Kapa çeneni yoksa ben kapatırım!": "Tutup mulutmu atau aku yang menutupnya!",
  "Kral mı? Son üç maçında yere kaç kez düştüğünü sayalım mı?": "Raja? Mau hitung berapa kali kamu jatuh di tiga laga terakhirmu?",
  "Kemeri evine asmışsın, güzel. Ben gelip alacağım.": "Sabuknya di dindingmu? Bagus. Aku akan datang mengambilnya.",
