  "Gülmeye devam et. Son gülen iyi güler.": "Terus tertawa. Yang tertawa terakhir yang tertawa paling keras.",
  "Ellerim titremiyor, sadece seni beklemekten sıkıldılar.": "Tanganku tidak gemetar. Cuma bosan menunggumu.",
