  "🔒 ya da ⤴️ görünce KONTROL. Rakip yorulunca SUB dene.": "Lihat 🔒 atau ⤴️? Tekan KONTROL. Incar SUB saat dia lelah.",
  "🔒 görünce hemen KURTUL. 👊 gelirken GARD al.": "Lihat 🔒? LANGSUNG LOLOS. Naikkan GARDA saat 👊 datang.",
  "Halka altın olunca KAÇ (⬇️ takedown'a karşı da). DİREKT ve TEKME hazırlığı keser.": "Saat lingkaran berubah emas, HINDARI (juga ampuh melawan takedown ⬇️). CROSS dan TENDANG memotong ancang-ancang.",
  "🤼 Yerde kontrol: {0} sn – {1} sn": "🤼 Kontrol bawah: {0}d – {1}d",
