  "Rakibi oku": "Baca lawanmu",
  "Rakip saldırı hazırlarken başında küçülen bir halka çıkar. Halka ALTIN olunca KAÇ'a bas, sonra hemen vur: kontra vuruşların çift hasar yapar.": "Saat lawan ancang-ancang, lingkaran mengecil muncul di sekitar kepalanya. Saat lingkaran berubah EMAS, tekan HINDARI, lalu langsung pukul: serangan balik memberi kerusakan ganda.",
  "Vur ve kes": "Pukul dan potong",
  "JAB hızlı ve ucuz, DİREKT ve TEKME ağırdır. Rakip hazırlanırken DİREKT ya da TEKME atarsan saldırısını kesersin. Sarı çubuk nefesin: bitince vuruşların zayıflar.": "JAB cepat dan hemat, CROSS dan TENDANG berat. Lempar CROSS atau TENDANG saat dia ancang-ancang untuk memotongnya. Bar kuning adalah tenagamu: saat habis, pukulanmu jadi lemah.",
  "İNDİR ile takedown dene; rakip ⬇️ ile dalarsa KAÇ ile sprawl yap. Yerde düğmeler değişir: üstteyken vur ve submission ara, alttayken 🔒 görünce hemen KURTUL.": "Coba TAKEDOWN; kalau dia menyergap dengan ⬇️, sprawl dengan HINDARI. Di bawah tombolnya berubah: di atas, pukul dan buru submission; di bawah, LOLOS begitu melihat 🔒.",
