  "İLK ADIMLAR": "LANGKAH PERTAMA",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. “İlk adımlar” sana yol gösterecek; maç yaptıkça yeni şeyler açılacak. Ama unutma, her şeyin bir bedeli var.": "Di atas ada uang, kesehatan, dan popularitasmu. Saat siap, pilih lawan lewat “ATUR PERTARUNGAN”. “Langkah pertama” akan memandumu; lebih banyak terbuka saat kamu bertarung. Tapi ingat, semuanya ada harganya.",
