  "Bas ya da basılı tut. DİREN! yanınca yeniden bas ve bırakma!": "Ketuk atau tahan. Saat TAHAN! menyala, tekan lagi dan jangan lepaskan!",
  "Çubuk dolarsa tap atarsın! Bas ya da basılı tut, kurtul!": "Kalau bar penuh, kamu tap! Ketuk atau tahan untuk lolos!",
  "DİREN!": "TAHAN!",
  "⚖️ Kilonu tartıdan önceki son 48 saatte kendin vereceksin. Bu organizasyonda hidrasyon testi var: kendini kurutma.": "⚖️ Kamu akan menurunkan berat sendiri di 48 jam terakhir sebelum timbang badan. Promosi ini melakukan tes hidrasi: jangan sampai tubuhmu kering.",
  "⚖️ Kilonu tartıdan önceki son 48 saatte kendin vereceksin. Su kesimini iyi yönetirsen kafese rakibinden iri çıkarsın.": "⚖️ Kamu akan menurunkan berat sendiri di 48 jam terakhir sebelum timbang badan. Atur buang cairan dengan baik dan kamu akan masuk lebih besar dari lawanmu.",
  "Son 48 saat: kilonu ver": "48 jam terakhir: lolos timbang",
  "🏆 Yükseliş Grand Prix'i daveti geldi! 8 amatör, tek kupa: şampiyon ve finalist profesyonel kapıyı açar.": "🏆 Undangan Rising Grand Prix! 8 amatir, satu trofi: juara dan finalis membuka pintu pro.",
  "🏆 Yükseliş Grand Prix'ine katıldın: 8 amatör, üç maç. Profesyonel organizasyonlar izliyor.": "🏆 Kamu masuk Rising Grand Prix: 8 amatir, tiga laga. Promosi pro mengawasi.",
  "Yükseliş Grand Prix'i Şampiyonu ({0})": "Juara Rising Grand Prix ({0})",
  "🏆 Yükseliş Grand Prix'ini kazandın! Organizasyonlar sıraya girdi: profesyonel kapı ardına kadar açık.": "🏆 Kamu memenangkan Rising Grand Prix! Promosi-promosi mengantre: pintu pro terbuka lebar.",
  "🥈 Finalde kaybettin ama herkes seni izledi. Profesyonel organizasyonlar seni kadrosunda istiyor!": "🥈 Kamu kalah di final, tapi semua orang menonton. Promosi pro ingin kamu di roster mereka!",
  "YÜKSELİŞ GRAND PRIX'İ DAVETİ": "UNDANGAN RISING GRAND PRIX",
  "Profesyonelliğe giden yolda vitrin: 8 amatör, üç maç (çeyrek final, yarı final, final). Kaybeden elenir. Şampiyon {0} ve kupayı alır; şampiyon da finalist de doğrudan profesyonel teklif alır. Davet yalnızca bir kez gelir.": "Etalasemu di jalan menuju pro: 8 amatir, tiga laga (perempat final, semifinal, final). Kalah dan kamu tersingkir. Sang juara mendapat {0} dan trofi; juara dan finalis sama-sama mendapat tawaran pro langsung. Undangan ini hanya datang sekali.",
