  "Alev desenli şort, ateş eldiveni, Ejderha çerçevesi ve kemeri, kafese ATEŞ efektiyle giriş": "Celana bermotif api, sarung tangan api, bingkai dan sabuk Naga, walkout dengan efek API",
  "Şimşek desenli buz şortu, buz eldiveni, Buz Kralı çerçevesi ve kemeri, kafese KAR FIRTINASI ile giriş": "Celana es bermotif petir, sarung tangan es, bingkai dan sabuk Raja Es, walkout di tengah BADAI SALJU",
