  "Bonus {0} adlı dövüşçüye gitti. Daha erken ve net bir bitiriş gerekiyordu.": "Bonus jatuh ke {0}. Kamu butuh finish yang lebih cepat dan bersih.",
  "Bonus {0} adlı dövüşçüye gitti. Bonus yarışına yalnızca bitirişler girer.": "Bonus jatuh ke {0}. Hanya finish yang bersaing untuk bonus.",
