  "{0} antrenmandan sonra seni kenara çekti: “Beni dinlemiyorsun. Böyle devam edeceksek yollarımızı ayıralım.”": "Setelah latihan, {0} menarikmu ke samping: “Kamu tidak mendengarkanku. Kalau begini terus, kita sebaiknya berpisah.”",
