  "Gururunu yuttun. {0} başını salladı: “Yarın sabah altıda.” Bağ toparlanıyor, motivasyon -1.": "Kamu menelan gengsimu. {0} mengangguk: “Jam enam pagi besok.” Ikatan mulai pulih, motivasi -1.",
  "Zam iyi geldi ama asıl önemli olan oturup konuşmanızdı. Bağ güçlendi.": "Kenaikan gaji membantu, tapi yang benar-benar penting adalah duduk dan bicara. Ikatan makin kuat.",
  "{0} ile yollarınız ayrıldı. Yeni hocan {1}. Sıfırdan bir güven kurmanız gerekecek. Motivasyon -1.": "Kamu dan {0} berpisah. Pelatih barumu {1}. Kamu harus membangun kepercayaan dari nol. Motivasi -1.",
  "🫂 Bir Baba Gibi": "🫂 Seperti Ayah",
  "Gece salonda yalnız kaldınız. {0} eski bir fotoğraf çıkardı: ilk antrenmanın, eldivenler elinden büyük. “O gün kapıdan girdiğinde ne olacağını biliyordum,” dedi.": "Larut malam, sendirian di sasana, {0} mengeluarkan foto lama: sesi pertamamu, sarung tangan lebih besar dari tanganmu. “Hari kamu masuk pintu itu, aku sudah tahu,” katanya.",
  "Sarıl": "Peluk dia",
  "“Her şeyi sana borçluyum.”": "“Aku berutang segalanya padamu.”",
  "{0} ile ilk antrenman fotoğrafı": "Foto sesi pertama bersama {0}",
  "Eldivenler elinden büyük. Arkasında hocanın el yazısı: “Bir gün.”": "Sarung tangan lebih besar dari tanganmu. Di baliknya, tulisan tangan pelatihmu: “Suatu hari.”",
  "Uzun süre konuşmadınız. Gerek yoktu. Motivasyon +2.": "Kalian berdua lama tak bicara. Tak perlu. Motivasi +2.",
  "“Hayır,” dedi, “her şeyi kendine borçlusun. Ben sadece kapıyı açtım.” Motivasyon +2.": "“Tidak,” katanya, “kamu berutang semuanya pada dirimu sendiri. Aku hanya membukakan pintu.” Motivasi +2.",
  "📨 Rakip Kampın Teklifi": "📨 Tawaran Kamp Rival",
  "Büyük bir salon {0} hocana baş antrenörlük teklif etmiş, maaşı iki katı. Sana söylemedi; sen başkasından duydun.": "Sebuah sasana besar menawari pelatihmu {0} posisi pelatih kepala dengan gaji dua kali lipat. Dia tidak memberitahumu; kamu dengar dari orang lain.",
  "Ona zam yap ve kalmasını iste ({0})": "Naikkan gajinya dan minta dia tetap ({0})",
  "Onu tebrik et, gitmesine izin ver": "Beri selamat dan lepaskan dia",
  "Sessiz kal, kararı ona bırak": "Diam saja, serahkan padanya",
  "{0} teklifi reddetti: “Benim dövüşçüm burada.” Bağ çok güçlendi.": "{0} menolaknya: “Petarungku ada di sini.” Ikatan jauh lebih kuat.",
  "{0} gözleri dolu gitti, giderken seni yeni hocan {1} ile tanıştırdı. Motivasyon +1.": "{0} pergi dengan mata berkaca-kaca, memperkenalkanmu pada pelatih barumu {1} saat pamit. Motivasi +1.",
  "{0} kaldı. “Sana sormadan karar vermem gerekirdi, ama burası benim evim,” dedi.": "{0} bertahan. “Seharusnya aku memutuskan tanpa bertanya padamu, tapi ini rumahku,” katanya.",
  "{0} teklifi kabul etti. Yeni hocan {1}.": "{0} menerima tawaran itu. Pelatih barumu {1}.",
  "🏥 Hocanın Sağlığı": "🏥 Kesehatan Pelatihmu",
  "{0} birkaç haftadır öksürüyordu. Doktorlar dinlenmesini söyledi ama o kampı bırakmak istemiyor.": "{0} sudah batuk berminggu-minggu. Dokter menyuruhnya istirahat, tapi dia menolak meninggalkan kamp.",
  "Zorla tatile gönder, kampı asistan yönetsin": "Paksa dia istirahat; biar asisten menjalankan kamp",
  "Onun kararına saygı duy": "Hormati keputusannya",
  "Önce kızdı, sonra teşekkür etti. Bir ay sonra eskisinden dinç döndü. Bağ güçlendi.": "Awalnya dia marah, lalu berterima kasih. Sebulan kemudian dia kembali lebih kuat dari sebelumnya. Ikatan tumbuh.",
  "Kampı yönetti ama her gece onu merak ettin. Motivasyon -1.": "Dia menjalankan kamp, tapi kamu mengkhawatirkannya setiap malam. Motivasi -1.",
  "🕊️ Hocanın Vedası": "🕊️ Perpisahan Pelatihmu",
  "{0} seni salonun ortasına çağırdı: “Yaşlandım evlat. Sana öğretebileceğim her şeyi öğrettim.” Yerine kendi asistanını önerdi.": "{0} memanggilmu ke tengah sasana: “Aku sudah tua, Nak. Semua yang bisa kuajarkan sudah kuajarkan.” Dia menyarankan asistennya mengambil alih.",
