  "Bir yapımcı seni “{0}” adlı aksiyon filminde kötü adam olarak istiyor. Çekimler üç hafta, Hollywood'dan bir yönetmen.": "Seorang produser ingin kamu jadi penjahat di film laga “{0}”. Tiga minggu syuting, sutradara Hollywood.",
  "Sette herkes senden korktu, sonra sevdi. Fragman bir günde 20 milyon izlendi.": "Semua orang di lokasi syuting takut padamu, lalu menyukaimu. Trailernya ditonton 20 juta kali dalam sehari.",
  "🎥 Belgesel Teklifi": "🎥 Tawaran Dokumenter",
  "Bir yayın platformu senin hayatını anlatan bir belgesel çekmek istiyor. Kamera ekibi bir sonraki kampın boyunca peşinde olacak; memleketine, ailene de gidecekler.": "Sebuah platform streaming ingin membuat dokumenter tentang hidupmu. Kru kamera akan mengikutimu di kamp berikutnya dan mengunjungi kampung halaman serta keluargamu.",
  "Kafesten Kemere": "Dari Kandang ke Sabuk",
  "Kamera her şeyi çekti: sabah koşularını, kesimin zor anlarını, annenin mutfağını. İzleyiciler seni tanıdı.": "Kamera menangkap segalanya: lari pagi, momen sulit menurunkan berat, dapur ibumu. Penonton jadi mengenalmu.",
  "📺 Reklam Yüzü": "📺 Wajah Kampanye",
  "{0} yeni kampanyasının yüzü olmanı istiyor. Bir günlük çekim, ülke çapında billboard.": "{0} ingin kamu jadi wajah kampanye barunya. Sehari syuting, baliho di seluruh negeri.",
  "Şehrin her köşesinde yüzün var. Annen her billboard'un fotoğrafını çekiyor.": "Wajahmu ada di setiap sudut kota. Ibumu memotret setiap baliho.",
  "🎙️ Talk Show Daveti": "🎙️ Undangan Talk Show",
  "“{0}” programı seni konuk olarak çağırdı. Sunucu ünlü, şaka kaldırırsa salon seninle.": "“{0}” mengundangmu sebagai bintang tamu. Pembawa acaranya terkenal; kalau kamu bisa menerima candaan, penonton milikmu.",
  "Sunucuya canlı yayında armbar gösterdin. Klip her yerde.": "Kamu memperagakan armbar ke pembawa acara di siaran langsung. Klipnya ada di mana-mana.",
  "📰 Dergi Kapağı": "📰 Sampul Majalah",
  "{0} dergisi seni kapağa koymak istiyor. Bir günlük çekim, büyük bir röportaj.": "Majalah {0} ingin kamu di sampulnya. Sehari pemotretan dan wawancara besar.",
  "Kapak büfelerde tükendi. Bir kopyası salonun duvarında.": "Edisinya ludes di kios. Satu eksemplar tergantung di dinding sasana.",
  "📺 Dizi Konuk Rolü": "📺 Peran Tamu Serial TV",
  "Sevilen dizi “{0}” bir bölümde seni kendini oynaman için istiyor. İki hafta çekim.": "Serial populer “{0}” ingin kamu memerankan dirimu sendiri di satu episode. Dua minggu syuting.",
  "Sahnen sosyal medyada dolaştı. Senaristler “bir sezon daha gel” diyor.": "Adeganmu beredar di media sosial. Para penulis ingin kamu kembali musim depan.",
