  "🕵️ Söylenti doğruydu: {0} sakat çıktı ve sen tam oraya hazırlandın (IQ +2).": "🕵️ Rumornya benar: {0} cedera dan kamu bersiap tepat untuk itu (IQ +2).",
  "🕵️ Söylenti blöftü: {0} sapasağlam. Planın boşa çıktı (IQ -2).": "🕵️ Rumornya gertakan: {0} sehat-sehat saja. Rencanamu jadi bumerang (IQ -2).",
  "🕵️ {0} gerçekten sakatmış ama sen planına sadık kaldın.": "🕵️ {0} memang cedera, tapi kamu tetap pada rencanamu sendiri.",
