  "🕵️ {0} gerçekten yeni bir planla geldi ama analizin onu çözdü (IQ +2).": "🕵️ {0} memang membawa rencana baru, tapi analisismu memecahkannya (IQ +2).",
  "🕵️ Analiz pahalıydı ama boşa değil: rakibi ezbere biliyorsun (IQ +2).": "🕵️ Analisisnya mahal tapi sepadan: kamu hafal lawanmu luar kepala (IQ +2).",
  "🕵️ {0} yeni hocasıyla bambaşka bir plan getirdi (rakip IQ +2).": "🕵️ {0} membawa rencana yang benar-benar berbeda dengan pelatih barunya (IQ lawan +2).",
  "🕵️ Zarftaki plan doğruydu: rakibinin her hamlesini önceden biliyorsun (IQ +3).": "🕵️ Rencana di amplop itu asli: kamu tahu setiap gerakan lawanmu sebelumnya (IQ +3).",
  "🕵️ Zarftaki plan sahteydi; parayı da güveni de kaybettin (IQ -1).": "🕵️ Rencana di amplop itu palsu; kamu kehilangan uang dan kepercayaan diri (IQ -1).",
  "Üstelik olay basına sızdı: popülerlik -4.": "Dan ceritanya bocor ke pers: popularitas -4.",
  "🕵️ Casusluk teklifini reddettin; kafeste temiz bir vicdanla duruyorsun.": "🕵️ Kamu menolak tawaran mata-mata; kamu berdiri di kandang dengan hati nurani bersih.",
  "Gece Bülteni": "Buletin Malam",
  "Kemer masada. Cumartesi gecesi kemerin kimin belinde olacak?": "Sabuk di atas meja. Di pinggang siapa sabuk itu Sabtu malam nanti?",
  "“Kemer, daha çok çalışanın olur. Ben çalıştım.”": "“Sabuk untuk yang bekerja lebih keras. Itu aku.”",
  "“Benim. Bunu şimdiden yazabilirsiniz.”": "“Milikku. Kalian bisa mencetaknya sekarang.”",
  "“Kemeri tartıya getirsinler, ölçülerimi alayım.”": "“Bawa sabuknya ke timbang badan, aku mau mengepas ukurannya.”",
  "Geçen sefer {0} seni yendi. Bu sefer ne değişecek?": "Terakhir kali {0} mengalahkanmu. Apa yang berubah kali ini?",
  "“O gece o daha iyiydi. Hatalarımı çalıştım.”": "“Malam itu dia lebih baik. Aku sudah memperbaiki kesalahanku.”",
  "“O gece bir kazaydı. Bu sefer erken bitireceğim.”": "“Malam itu kebetulan. Kali ini aku akan menyelesaikannya cepat.”",
  "“Değişen tek şey saç modelim. Bir de sonuç.”": "“Satu-satunya yang berubah adalah potongan rambutku. Dan hasilnya.”",
  "Kendi seyircinin önünde dövüşeceksin. Baskı hissediyor musun?": "Kamu bertarung di depan pendukungmu sendiri. Merasa tertekan?",
  "“Onların önünde dövüşmek bir onur.”": "“Bertarung di depan mereka adalah kehormatan.”",
  "“Baskıyı o hissetsin. Burası benim evim.”": "“Biar dia yang merasa tertekan. Ini rumahku.”",
  "“Annem ön sırada olacak, asıl baskı o.”": "“Ibuku akan duduk di barisan depan. Itu tekanan sesungguhnya.”",
  "Üst üste kaybettin. Bazıları bitti diyor. Ne diyorsun?": "Kamu kalah dua kali berturut-turut. Ada yang bilang kamu sudah habis. Apa katamu?",
  "“Eleştirileri hak ettim. Cevabımı kafeste vereceğim.”": "“Aku pantas dikritik. Akan kujawab di kandang.”",
  "“Beni gömenler cumartesi tribünde olsun.”": "“Semua yang menguburku sebaiknya ada di tribun Sabtu nanti.”",
  "“Bitmedim, sadece uzun bir ısınma turundaydım.”": "“Aku belum habis, aku cuma sedang pemanasan panjang.”",
  "{0} hakkında ne düşünüyorsun?": "Apa pendapatmu tentang {0}?",
  "“Saygı duyduğum bir dövüşçü. Zor bir maç olacak.”": "“Petarung yang kuhormati. Ini akan jadi laga berat.”",
  "“Abartılan bir isim. Cumartesi herkes görecek.”": "“Nama yang terlalu dibesar-besarkan. Semua akan lihat Sabtu nanti.”",
  "“Sakalı güzel. Gerisini kafeste konuşuruz.”": "“Jenggotnya bagus. Sisanya kita bicarakan di kandang.”",
  "Maç nasıl biter? Bir tahmin ver.": "Bagaimana laga berakhir? Beri prediksi.",
  "“Kim daha iyi hazırlandıysa o kazanır.”": "“Yang persiapannya lebih baik akan menang.”",
  "“İkinci raunt, nakavt. Not alın.”": "“Ronde kedua, KO. Catat itu.”",
  "“Ben kazanırım, o da güzel bir uyku çeker.”": "“Aku menang, dia dapat tidur siang yang nyenyak.”",
  "Kamp nasıl geçti?": "Bagaimana kampnya?",
  "“Zor ama verimli. Ekibime teşekkür ederim.”": "“Berat tapi produktif. Terima kasih untuk timku.”",
  "“Hayatımın en iyi kampı. Daha önce hiç bu kadar hazır olmadım.”": "“Kamp terbaik dalam hidupku. Aku belum pernah sesiap ini.”",
  "“Hocam beni o kadar koşturdu ki ayakkabılarım istifa etti.”": "“Pelatihku menyuruhku lari sampai sepatuku menyerah.”",
  "Salon saygıyla alkışladı. Hocan başını salladı.": "Ruangan bertepuk tangan dengan hormat. Pelatihmu mengangguk.",
  "Flaşlar patladı! Manşetler hazır; şimdi sözünü tutman gerek.": "Kilatan kamera di mana-mana! Judul berita sudah ditulis; sekarang kamu harus membuktikannya.",
  "Salon kahkahaya boğuldu, klip şimdiden dolaşıyor.": "Ruangan tertawa terbahak-bahak; klipnya sudah beredar.",
