  "🎤 Basın toplantısında büyük konuştun ama kaybettin. Manşet: “Sözünü yedi.” Popülerlik -{0}": "🎤 Kamu bicara besar di konferensi pers tapi kalah. Judul: “Dia menelan kata-katanya.” Popularitas -{0}",
