  "Esprili": "Jenaka",
  "Büyük konuştun. Şimdi kafeste sözünü tutman gerek: kazanırsan alkış, kaybedersen manşetler acımaz.": "Kamu sudah bicara besar. Sekarang buktikan di kandang: menang dan kamu dapat tepuk tangan, kalah dan judul berita tak akan ramah.",
