  "{0} seni bayramla karşıladı. Eski salonun kapısına adın yazıldı. Motivasyon tavan, popülerlik +4.": "{0} menyambutmu seperti hari raya. Namamu dipasang di pintu sasana lamamu. Motivasi maksimal, popularitas +4.",
