  "{0} artık senin menajerin. Komisyon yüksek (%{1}) ama kapılar ardına kadar açık. Popülerlik +3, +{2} takipçi.": "{0} kini manajermu. Komisinya tinggi ({1}%) tapi semua pintu terbuka. Popularitas +3, +{2} pengikut.",
  "Kötü adam dönemi": "Era penjahat",
  "İmajını değiştir: herkesin sevmekten nefret ettiği adam ol": "Ubah citramu: jadi orang yang semua orang suka benci",
  "Siyah takım elbise, kibirli bakışlar, her röportajda bir bomba. Tribünler seni yuhalıyor ama herkes izliyor. Popülerlik +6, +{0} takipçi; hocan pek memnun değil.": "Jas hitam, tatapan angkuh, bom di setiap wawancara. Tribun menyorakimu tapi semua orang menonton. Popularitas +6, +{0} pengikut; pelatihmu tidak senang.",
  "Sessiz yıllar": "Tahun-tahun tenang",
  "Üç ay ara ver, ailene ve kendine zaman ayır": "Ambil cuti tiga bulan untuk keluarga dan dirimu",
  "Telefonu kapattın, üç ay boyunca sadece yaşadın. Vücudun ve kafan yenilendi (sağlık 100, motivasyon tavan) ama gündemden düştün (popülerlik -3). {0}": "Kamu mematikan ponsel dan hanya menjalani hidup selama tiga bulan. Tubuh dan pikiran segar (kesehatan 100, motivasi maksimal) tapi kamu hilang dari berita (popularitas -3). {0}",
  "Boks macerası": "Petualangan tinju",
  "Boks dünyasına kapıyı arala, süper maç kovala": "Buka pintu ke tinju dan kejar laga super",
  "Boks salonlarında görünmeye başladın, menajerin telefonları açtı. Bir süper maç teklifi gelmesi an meselesi (popülerlik +3).": "Kamu mulai muncul di sasana tinju dan manajermu sibuk menelepon. Tawaran laga super tinggal soal waktu (popularitas +3).",
  "Kariyerinin bir yol ayrımındasın. Önümüzdeki yıllar nasıl geçecek?": "Kariermu di persimpangan. Bagaimana tahun-tahun mendatang?",
