  "Her şey yolunda, devam": "Semua baik, lanjutkan",
  "Hiçbir şeyi değiştirmedin. Bazen en iyi karar, yola devam etmektir.": "Kamu tidak mengubah apa pun. Kadang keputusan terbaik adalah terus melangkah.",
  "🧭 {0} için yeni bir dönem: {1}": "🧭 Era baru untuk {0}: {1}",
  "💌 Hastaneden Bir Mektup": "💌 Surat dari Rumah Sakit",
  "Çocuk hastanesinden bir mektup: “Her maçını yatağımdan izliyorum. Kemoterapi günlerinde senin nakavtlarını açıyorum. Bir gün gelir misin?”": "Surat dari rumah sakit anak: “Aku menonton setiap laga dari ranjangku. Di hari kemoterapi aku memutar KO-mu. Maukah kamu datang suatu hari?”",
  "Hastaneye git": "Kunjungi rumah sakit",
  "İmzalı bir eldiven gönder": "Kirim sarung tangan bertanda tangan",
  "Bütün koğuşu gezdin, her çocukla fotoğraf çektirdin. Gece eve döndüğünde uzun süre uyuyamadın. Popülerlik +3, motivasyon +2.": "Kamu mengunjungi seluruh bangsal dan berfoto dengan setiap anak. Pulang malam itu, kamu lama tak bisa tidur. Popularitas +3, motivasi +2.",
  "Annesinden bir fotoğraf geldi: eldiven yatağın başucunda asılı. Popülerlik +1.": "Ibunya mengirim foto: sarung tangan itu tergantung di atas ranjang. Popularitas +1.",
  "📱 Kırgın Bir Taraftar": "📱 Penggemar yang Kecewa",
  "Bir taraftar uzun bir mesaj yazmış: “Senin için maçın biletine maaşımı verdim. Bu gece beni utandırdın.”": "Seorang penggemar menulis pesan panjang: “Aku menghabiskan gajiku untuk tiket demi kamu. Malam ini kamu mempermalukanku.”",
  "Özür dile ve söz ver": "Minta maaf dan berjanji",
  "Sert bir cevap yaz": "Tulis balasan keras",
  "“Bir dahaki sefere o bilet sana değecek.” Mesajın ekran görüntüsü yayıldı, insanlar dürüstlüğünü sevdi. Motivasyon +1, popülerlik +1.": "“Lain kali, tiket itu akan sepadan.” Tangkapan layar balasanmu menyebar dan orang menyukai kejujuranmu. Motivasi +1, popularitas +1.",
  "Görmezden geldin. Bazı geceler susmak en iyisi.": "Kamu mengabaikannya. Ada malam di mana diam adalah yang terbaik.",
  "Cevabın ekran görüntüsü her yerde. “Taraftarına bağıran yıldız” manşeti çıktı. Popülerlik -3.": "Tangkapan layar balasanmu ada di mana-mana. Judul: “Bintang membentak penggemarnya sendiri.” Popularitas -3.",
  "✉️ Rakibin Annesinden": "✉️ Dari Ibu Lawanmu",
  "Son rakibinin annesi el yazısıyla bir mektup göndermiş: “Oğlum iyi, merak etme. Sana kızgın değilim. Sadece bir dahaki sefere yerde kalan birine biraz daha nazik ol.”": "Ibu lawan terakhirmu mengirim surat tulisan tangan: “Anakku baik-baik saja, jangan khawatir. Aku tidak marah padamu. Lain kali, sedikit lebih lembutlah pada orang yang sudah jatuh.”",
  "Çiçek ve bir not gönder": "Kirim bunga dan catatan",
  "Mektubu sakla, kimseye söyleme": "Simpan suratnya, jangan beri tahu siapa pun",
  "Kadın notunu sosyal medyada paylaştı: “Kafeste rakip, dışarıda bir evlat.” Popülerlik +2.": "Dia membagikan catatanmu di internet: “Rival di kandang, anak di luarnya.” Popularitas +2.",
  "Mektup çekmecende duruyor. Her maçtan önce bir kez okuyorsun. Motivasyon +1.": "Surat itu tersimpan di lacimu. Kamu membacanya sekali sebelum setiap laga. Motivasi +1.",
  "📞 Eski Bir Okul Arkadaşı": "📞 Teman Sekolah Lama",
  "İlkokuldan sıra arkadaşın aradı. Yıllardır konuşmuyordunuz. Küçük bir dükkân açmak istiyor, senden ${0} borç istiyor.": "Teman sebangkumu di SD menelepon. Kalian sudah bertahun-tahun tak bicara. Dia ingin membuka toko kecil dan meminjam ${0}.",
  "Bir yıl sonra dükkânın vitrininde senin posterin ve yanında bir zarf: borcun tamamı. Motivasyon +1.": "Setahun kemudian: postermu di etalase toko dan amplop di sebelahnya berisi pinjaman penuh. Motivasi +1.",
  "Dükkân tutmadı, arkadaşın bir daha aramadı. Para gitti ama kalbin rahat.": "Tokonya bangkrut dan temanmu tak pernah menelepon lagi. Uangnya hilang tapi hatimu tenang.",
  "Anladığını söyledi. Yine de sesindeki kırgınlığı duydun.": "Dia bilang mengerti. Tapi kamu mendengar kekecewaan di suaranya.",
  "🥋 Genç Bir Dövüşçü Adayı": "🥋 Calon Petarung Muda",
  "On altı yaşında biri yazmış: “Ailem dövüşmemi istemiyor. Okulu bırakıp salona mı yazılsam?”": "Seorang remaja enam belas tahun menulis: “Keluargaku tak ingin aku bertarung. Haruskah aku putus sekolah dan masuk sasana?”",
  "“Önce okulunu bitir, salon kaçmaz.”": "“Selesaikan sekolah dulu. Sasana tidak akan ke mana-mana.”",
  "“Hayallerinin peşinden git.”": "“Kejar mimpimu.”",
  "Birkaç ay sonra bir fotoğraf geldi: diploması bir elinde, eldivenleri diğerinde. Popülerlik +1.": "Beberapa bulan kemudian sebuah foto datang: ijazah di satu tangan, sarung tangan di tangan lain. Popularitas +1.",
  "Seni idolü olarak gösteren bir video çekti; yorumlarda aileler ikiye bölündü. Popülerlik +1.": "Dia membuat video menyebutmu idolanya; para orang tua di kolom komentar terbelah. Popularitas +1.",
  "😠 Nefret Mesajları": "😠 Pesan Kebencian",
  "Bir hesap haftalardır her paylaşımının altına hakaret yazıyor. Bugün ailene de laf etmiş.": "Satu akun sudah berminggu-minggu menghinamu di setiap postingan. Hari ini dia juga menyerang keluargamu.",
  "Engelle ve geç": "Blokir dan lanjutkan",
