  "Herkesin önünde sert cevap ver": "Balas dengan keras di depan umum",
  "Engelledin, telefonu kapattın. Kafan rahatladı. Motivasyon +1.": "Kamu memblokirnya dan meletakkan ponsel. Kepalamu jernih. Motivasi +1.",
  "Cevabın o kadar komikti ki hesap kendini kapattı. {0} takipçi.": "Balasanmu begitu lucu sampai akunnya menghapus diri. {0} pengikut.",
  "Tartışma günlerce sürdü; sen de yoruldun. Popülerlik -1, motivasyon -1.": "Perdebatan berlarut berhari-hari dan membuatmu lelah. Popularitas -1, motivasi -1.",
  "🎨 Bir Hayranın Hediyesi": "🎨 Hadiah dari Penggemar",
  "Bir ressam hayranın, senin kemer kaldırdığın bir portreyi postayla göndermiş. Altında: “Bir gün bu gerçek olacak.”": "Seorang penggemar pelukis mengirimimu potret dirimu mengangkat sabuk. Di bawahnya: “Suatu hari ini akan jadi nyata.”",
