  "Eski salonun yeni minderleri, yeni torbaları ve senin adını taşıyan tabelasıyla açıldı. Çocuklar sıraya girdi. Popülerlik +3, motivasyon +1 (${0}).": "Sasana lamamu dibuka kembali dengan matras baru, samsak baru, dan papan bertuliskan namamu. Anak-anak mengantre. Popularitas +3, motivasi +1 (${0}).",
  "Meydanda yürüyemedin bile; herkes fotoğraf istedi. Annenin yemeği her şeye değdi. Motivasyon +1, sağlık +5, popülerlik +1.": "Kamu bahkan tak bisa menyeberangi alun-alun; semua orang ingin berfoto. Masakan ibumu sepadan dengan semuanya. Motivasi +1, kesehatan +5, popularitas +1.",
