  "Kamera yokken de bu kadar cesur musun? Kafeste göreceğiz.": "Apakah kamu seberani ini saat kamera mati? Kita lihat di kandang.",
  "Senin videolarını izledim. Açığını buldum bile. 😴": "Aku sudah menonton rekamanmu. Kelemahanmu sudah ketemu. 😴",
