  "Selam. Kampın iyi geçsin, sağlıklı gel. Kafeste en iyi hâllerimizle karşılaşalım. 🤝": "Hai. Semoga kampmu lancar, datang dalam keadaan sehat. Mari bertemu dalam kondisi terbaik di kandang. 🤝",
  "Kariyerini uzun zamandır izliyorum. Bu maç ikimiz için de büyük fırsat. Başarılar.": "Aku sudah lama mengikuti kariermu. Laga ini kesempatan besar bagi kita berdua. Semoga sukses.",
