  "Alay et 😏": "Ejek dia 😏",
  "Karşılıklı saygı. İçin rahat, kampa odaklandın: motivasyon +1, popülerlik +1.": "Saling menghormati. Kepala jernih, fokus ke kamp: motivasi +1, popularitas +1.",
  "Alaycı DM": "DM mengejek",
  "Rakip mesajı paylaştı: “Saygı gösterdim, karşılığı bu.” Gündem yükseldi ama bazı hayranlar soğudu. Takipçi {0}.": "Lawanmu mempostingnya: “Aku menunjukkan respek, dan ini yang kudapat.” Gaung naik tapi sebagian penggemar mulai dingin. Pengikut {0}.",
  "Promotör ofisi": "Kantor promotor",
  "Maçı satmamız lazım. Önümüzdeki hafta 3 şehirde basın turu ayarlayabiliriz. Yorucu ama bilet satışını uçurur. Var mısın?": "Kita perlu menjual laga ini. Kita bisa adakan tur pers 3 kota minggu depan. Melelahkan, tapi penjualan tiket akan melesat. Kamu ikut?",
