  "Tur olay oldu, biletler kapışılıyor. Ama yol yorgunluğu kampı biraz bozdu: motivasyon -1. Takipçi {0}.": "Turnya sukses, tiket laris. Tapi perjalanan membuatmu lelah: motivasi -1. Pengikut {0}.",
  "Promotör homurdandı ama kampına dokunmadın: motivasyon +1.": "Promotor menggerutu, tapi kamu melindungi kampmu: motivasi +1.",
  "Kamp başlamadan bu akşam baş başa bir yemek? Sonra haftalarca yüzünü göremeyeceğim. ❤️": "Makan malam berdua malam ini sebelum kamp mulai? Aku tak akan bertemu kamu berminggu-minggu sesudahnya. ❤️",
  "Tabii, rezervasyon benden": "Tentu, aku pesan meja",
  "Maçtan sonra telafi ederim": "Akan kutebus setelah laga",
  "Güzel bir akşamdı. Kafan rahat kampa girdin: motivasyon +1 (−{0}).": "Malam yang indah. Kamu masuk kamp dengan kepala jernih: motivasi +1 (−{0}).",
  "“Söz mü?” dedi. Söz verdin. Maçtan sonra unutma.": "“Janji?” Kamu berjanji. Jangan lupa setelah laga.",
  "Annem": "Ibu",
  "Oğlum yine maçın varmış, komşudan duydum. Yemeğini düzgün ye, kilo vereceğim diye kendini aç bırakma. Dua ediyorum.": "Dengar dari tetangga kamu ada laga lagi. Makan yang benar, jangan menyiksa diri saat menurunkan berat. Ibu mendoakanmu.",
  "Baban maçı büyük ekranda izleyecekmiş, bütün mahalleyi çağırdı. Dikkat et kendine yavrum.": "Ayahmu nonton di layar besar, dia mengundang satu kampung. Jaga dirimu, sayang.",
