  "“Merak etme anne” yaz": "Kirim pesan “Jangan khawatir, Bu”",
  "Yarım saat konuştunuz. Sesini duymak iyi geldi: motivasyon +1.": "Kalian bicara setengah jam. Mendengar suaranya membantu: motivasi +1.",
  "“Tamam yavrum, Allah utandırmasın” yazdı. ❤️": "Dia menulis: “Baik sayang, Tuhan bersamamu.” ❤️",
  "Rakibinin stilini taklit edebilirim. Bu akşam salon kapanınca ekstra spar yapalım mı? 🥊": "Aku bisa meniru gaya lawanmu. Sparring tambahan malam ini setelah sasana tutup? 🥊",
  "Yapalım": "Ayo",
  "Bu akşam dinlenmem lazım": "Aku butuh istirahat malam ini",
  "Sert ama faydalı bir spar. Bağınız güçlendi, biraz yıprandın (sağlık −3).": "Sparring berat tapi berguna. Ikatan kalian tumbuh, kamu sedikit lelah (kesehatan −3).",
  "“Peki kanka” yazdı. Biraz bozulmuş gibi.": "Dia menulis “Oke bro.” Kelihatannya agak kecewa.",
  "Şanslıydın. Bunu ikimiz de biliyoruz. Rövanşta gerçeği göreceksin.": "Kamu beruntung. Kita berdua tahu itu. Di laga ulang kamu akan lihat kebenarannya.",
  "Bu gece daha iyiydin, tebrik ederim. Bir gün rövanş isterim ama önce kendimi toparlayacağım. 🤝": "Kamu lebih baik malam ini, selamat. Suatu hari aku ingin laga ulang, tapi aku berbenah dulu. 🤝",
