  "Hocam": "Pelatih",
  "Kafana takma. Yarın sabah salona erken gel, maçı birlikte izleyelim. Neyi yanlış yaptığımızı ben de görmek istiyorum.": "Jangan dipikirkan terus. Datang ke sasana pagi-pagi besok, kita tonton laganya bersama. Aku juga ingin melihat apa yang salah.",
