  "Birkaç gün kafa dinleyeceğim": "Aku butuh libur beberapa hari",
  "Maçı kare kare izlediniz. Hocanla bağın güçlendi.": "Kalian membedah laga bingkai demi bingkai. Ikatanmu dengan pelatih tumbuh.",
  "Biraz uzaklaştın, iyi geldi: motivasyon +1. Hocan biraz kırıldı.": "Sedikit jarak membantu: motivasi +1. Pelatihmu agak kecewa.",
  "Gurur duydum. Ama şımarmak yok, pazartesi idmandayız. 😄": "Bangga padamu. Tapi jangan sombong, latihan hari Senin. 😄",
  "Her şey senin sayende hocam": "Ini semua berkat Anda, pelatih",
  "Pazartesi ilk ben gelirim": "Aku yang pertama datang hari Senin",
  "Hocan duygulandı. Bağınız güçlendi.": "Pelatihmu terharu. Ikatan kalian tumbuh.",
  "“Göreceğiz” dedi. Motivasyon +1.": "“Kita lihat saja,” katanya. Motivasi +1.",
