  "Kemeri almak zor, tutmak daha zor. Hoş geldin şampiyon. Bir gün kahve içelim, anlatacak çok şeyim var.": "Merebut sabuk itu sulit, mempertahankannya lebih sulit. Selamat datang, juara. Kapan-kapan kita ngopi, banyak yang ingin kuceritakan.",
