  "Mesajı paylaştın, herkes konuşuyor: popülerlik +2, motivasyon +1.": "Kamu membagikan pesan itu, semua orang membicarakannya: popularitas +2, motivasi +1.",
  "Senin maçını izledikten sonra salona yazıldım! Annem bir sesli mesaj atarsan çok mutlu olacağımı söyledi. Lütfen 🥺": "Aku masuk sasana setelah menonton laga kamu! Ibuku bilang pesan suara darimu akan membuatku sangat senang. Tolong 🥺",
  "Sesli mesaj gönder 🎙️": "Kirim pesan suara 🎙️",
