  "Annesi videoyu paylaştı, çocuk sevinçten ağlıyor. Motivasyon +1. Takipçi {0}.": "Sang ibu memposting videonya, anaknya menangis bahagia. Motivasi +1. Pengikut {0}.",
  "Eldiveni odasının duvarına asmış. Haber oldu: popülerlik +1 (−{0}).": "Sarung tangan itu tergantung di dinding kamar si anak. Masuk berita: popularitas +1 (−{0}).",
