  "Hayat hikâyeni anlatacağın özel bir röportaj yapmak istiyoruz. Çocukluğun, ilk salonun, hayallerin… Ne dersin?": "Kami ingin wawancara eksklusif tentang kisah hidupmu. Masa kecil, sasana pertamamu, mimpi-mimpimu… Bagaimana?",
