  "Ünlü sporcular için özel coin ön satışı! {0} yatır, 1 ayda 10 katı garanti. 🚀🚀 Sadece bugün!": "Presale koin eksklusif untuk atlet bintang! Investasi {0}, dijamin 10x dalam sebulan. 🚀🚀 Hari ini saja!",
