  "Hey şampiyon, büyük hayranınım! Bir sonraki maçına gelmek istiyorum. Bilet ayarlayabilir misin? 🙏": "Hai juara, penggemar beratmu! Aku ingin datang ke laga berikutnya. Bisa carikan tiket? 🙏",
