  "Kafes kenarında kameralar onu gösterecek, adın her yerde: popülerlik +1 (−{0}). Takipçi {1}.": "Kamera akan menyorot dia di pinggir kandang, namamu ada di mana-mana: popularitas +1 (−{0}). Pengikut {1}.",
  "Menajerin halletti. Kibar ama mesafeli.": "Manajermu yang mengurusnya. Sopan tapi berjarak.",
