  "Bu hafta antrenman var": "Latihan minggu ini",
  "İki gün deniz, güneş ve sessizlik. Sağlık +4, motivasyon +1 (−{0}).": "Dua hari laut, matahari, dan ketenangan. Kesehatan +4, motivasi +1 (−{0}).",
  "“Anlıyorum ama sıradaki tatil benden” yazdı.": "Dia menulis: “Aku mengerti, tapi perjalanan berikutnya aku yang pilih.”",
  "Senin portreni çizdim, üç gece uğraştım! 🎨 Beğenir misin?": "Aku menggambar potretmu, butuh tiga malam! 🎨 Kamu suka?",
  "Hikâyemde paylaşacağım ❤️": "Akan kubagikan di story-ku ❤️",
  "Çizim yayıldı, sanatçı da sen de kazandınız. Takipçi {0}.": "Gambarnya menyebar, kamu dan senimannya sama-sama untung. Pengikut {0}.",
