  "Rakiplerin, hayranların ve sponsorların maçlar yaklaştıkça yazmaya başlar.": "Lawan, penggemar, dan sponsor mulai menulis saat laga makin dekat.",
  "Sen: {0}": "Kamu: {0}",
  "Bu mesajın cevap süresi geçti.": "Sudah terlambat untuk membalas pesan ini.",
  "CEVAP SEÇ": "PILIH BALASAN",
