  "Kaşın açıldı, gözüne akan kanla dövüşmeye devam ettin.": "Alismu robek, kamu terus bertarung dengan darah di mata.",
  "{0} yediği yumrukla yere gitti!": "{0} menghantam kanvas karena pukulanmu!",
  "{0} seni yere gönderdi.": "{0} menjatuhkanmu.",
  "{0} bu raunt {1} kez yere gitti!": "{0} jatuh {1} kali di ronde ini!",
  "Sarsıldın ama ayakta kalıp raundu bitirdin.": "Kamu goyah tapi tetap berdiri sampai ronde selesai.",
  "{0} isabetli vuruşla raundu domine ettin.": "Kamu mendominasi ronde dengan {0} pukulan kena.",
  "Bitirmek üzereyken {0} umutsuz bir kontrayla seni yakaladı.": "Tepat saat kamu mengincar finish, {0} mengenaimu dengan serangan balik nekat.",
  "Sarsılmışken savurduğun sağ el {0} dövüşçüsünü de sarstı!": "Meski terluka, tangan kananmu juga menggoyahkan {0}!",
  "Ağır sarsıldın ama dişini sıkıp raundu kurtardın.": "Kamu terluka parah tapi mengertakkan gigi dan bertahan di ronde itu.",
  "{0} kilidini sonuna kadar sıktın, {1} son anda kurtuldu.": "Kamu menekan {0} sampai batas, {1} lolos di detik terakhir.",
  "MAÇIN EN İYİ ANLARI": "SOROTAN LAGA",
  "{0} yeni mesaj": "{0} pesan baru",
  "Yıllar ağır basıyor: hız, çene ve kondisyon belirgin şekilde düştü. Veda maçını düşünme zamanı olabilir.": "Usia terasa berat: kecepatan, dagu, dan kardio turun drastis. Mungkin saatnya memikirkan laga perpisahan.",
  "Vücut eskisi gibi toparlanmıyor: hız, çene, kondisyon ve vuruş düştü, ama tecrübe arttı.": "Tubuh tak pulih seperti dulu: kecepatan, dagu, kardio, dan striking turun, tapi pengalaman bertambah.",
  "Puan kazanmak için kamp yap ve dövüş. Galibiyet ve bitiriş daha çok kazandırır. Maliyet: 60’a kadar 1, 78’e kadar 2, 90’a kadar 3, sonrası 4 puan.": "Dapatkan poin dengan menjalani kamp dan bertarung. Kemenangan dan finish memberi lebih banyak. Biaya: 1 poin sampai 60, 2 sampai 78, 3 sampai 90, lalu 4.",
  "Yaş sınırı: 33’ten sonra hız, çene ve kondisyon; 35’ten sonra vuruş, güreş ve yer her yıl biraz daha aşağıda tavan yapar. IQ yaşlanmaz.": "Batas usia: setelah 33, kecepatan, dagu, dan kardio; setelah 35, striking, gulat, dan bawah sedikit lebih rendah batasnya setiap tahun. IQ tidak menua.",
  "DWCS'ye hazır ol: şampiyon ol, ya da ilk 3'te popülerlik 20+, ya da ilk 5'te 2 maçlık seri, ya da ilk 8'de 3 maçlık seri, ya da 4 maç yenilmeden git": "Siap DWCS: jadilah juara, atau 3 besar dengan popularitas 20+, atau 5 besar dengan rentetan 2 laga, atau 8 besar dengan rentetan 3 laga, atau 4 laga tak terkalahkan",
  "Kazandın ama Dean tam ikna olmadı: \"Bir galibiyet daha getir, kapı açık.\" Bir sonraki galibiyetin UCC kontratını getirecek.": "Kamu menang, tapi Dean belum sepenuhnya yakin: \"Bawakan satu kemenangan lagi, pintunya terbuka.\" Kemenangan berikutnya akan membawa kontrak UCC.",
  "🎟️ Dean Wyatt sözünü tuttu: \"{0}, istediğim galibiyeti getirdin. UCC’ye hoş geldin!\"": "🎟️ Dean Wyatt menepati janjinya: \"{0}, kamu membawakan kemenangan yang kuinginkan. Selamat datang di UCC!\"",
  "👋 {0} son maçını ilan etti: \"Bir kez daha kafese çıkacağım, sonra eldivenleri asacağım.\"": "👋 {0} mengumumkan laga terakhirnya: \"Aku akan masuk kandang sekali lagi, lalu gantung sarung tangan.\"",
  "🚨 SON DAKİKA: {0} veda maçının tarihini verdi. Bir devrin sonu yaklaşıyor.": "🚨 TERKINI: {0} telah menetapkan tanggal laga perpisahannya. Akhir sebuah era sudah dekat.",
  "👋 VEDA MAÇI": "👋 LAGA PERPISAHAN",
  "Kariyerinin son maçı, tanıdık bir yüzle. Sonuç ne olursa olsun bu gece salon senin için ayakta.": "Laga terakhir kariermu, melawan wajah yang familiar. Apa pun yang terjadi, arena berdiri untukmu malam ini.",
  "Kariyerinin son maçı. Sonuç ne olursa olsun bu gece salon senin için ayakta.": "Laga terakhir kariermu. Apa pun yang terjadi, arena berdiri untukmu malam ini.",
  "👋 {0} kariyerini galibiyetle kapattı. Salon dakikalarca ayakta alkışladı.": "👋 {0} menutup kariernya dengan kemenangan. Arena memberi standing ovation selama bermenit-menit.",
  "👋 {0} son maçında kaybetti ama salon onu ayakta uğurladı.": "👋 {0} kalah di laga terakhirnya, tapi arena melepasnya dengan standing ovation.",
  "Teşekkürler {0}. Her maçında ayağa kalktık, bu gece de kalktık. 👋❤️": "Terima kasih {0}. Kami berdiri di setiap laga, dan kami berdiri malam ini juga. 👋❤️",
  "👋 VEDA GALİBİYETİ! Son maçını kazanarak bırakıyorsun. Popülerlik +8.": "👋 KEMENANGAN PERPISAHAN! Kamu pergi dengan kemenangan. Popularitas +8.",
  "👋 Son maç istediğin gibi bitmedi. Ama salon seni ayakta uğurladı. Popülerlik +4.": "👋 Laga terakhir tidak berpihak padamu. Tapi arena melepasmu sambil berdiri. Popularitas +4.",
  "🥋 {0}: \"Salona ilk girdiğin gün ellerin titriyordu. Bak şimdi… Seninle gurur duyuyorum evlat.\"": "🥋 {0}: \"Hari pertama kamu masuk sasana, tanganmu gemetar. Lihat dirimu sekarang… Aku bangga padamu, Nak.\"",
  "🥋 {0}: \"Bu gece kaybetmedin. Bu kariyer, bu salon, bu insanlar… hepsi senin zaferin.\"": "🥋 {0}: \"Kamu tidak kalah malam ini. Karier ini, sasana ini, orang-orang ini… semuanya adalah kemenanganmu.\"",
  "VEDA MAÇI": "LAGA PERPISAHAN",
  "{0} yaşındasın. İstersen son maçını ilan et: büyük bir rakip, gecenin ana maçı ve seni ayakta uğurlayan bir salon. Maçtan sonra eldivenleri asarsın.": "Usiamu {0}. Kalau mau, umumkan laga terakhirmu: lawan besar, main event malam itu, dan arena yang melepasmu sambil berdiri. Sesudahnya, kamu gantung sarung tangan.",
  "Veda maçını ilan et": "Umumkan laga perpisahan",
  "Emin misin? Bir sonraki maç kariyerinin son maçı olacak; sonucu ne olursa olsun ardından emekli olacaksın.": "Kamu yakin? Laga berikutnya akan jadi yang terakhir dalam kariermu; apa pun hasilnya, kamu akan pensiun sesudahnya.",
  "İlan et": "Umumkan",
  "{0} karşısında {1} ile kazandın.": "Kamu mengalahkan {0} lewat {1}.",
  "{0} ile berabere kaldın.": "Kamu seri dengan {0}.",
  "{0} karşısında kaybettin.": "Kamu kalah dari {0}.",
  "Son zil çaldığında hakem kolunu kaldırdı. Salon dakikalarca ayakta alkışladı; kafesin ortasında eldivenlerini çıkarıp yere bıraktın.": "Saat bel terakhir berbunyi, wasit mengangkat tanganmu. Arena bertepuk tangan sambil berdiri selama bermenit-menit; di tengah kandang kamu melepas sarung tanganmu dan meletakkannya.",
  "Kol senin için kalkmadı ama salonda oturan kimse kalmadı. Kafesin ortasında eldivenlerini çıkarıp yere bıraktın; alkışlar uzun süre dinmedi.": "Tanganmu tidak diangkat, tapi tak seorang pun di arena tetap duduk. Di tengah kandang kamu melepas sarung tanganmu dan meletakkannya; tepuk tangan berlangsung lama.",
  "Önce mesafeyi ölç. JAB hızlı ve ucuz: bas bakalım!": "Pertama, temukan jarakmu. JAB cepat dan hemat: ayo, tekan!",
  "Rakip saldırıya hazırlanıyor, halka ALTIN oldu! Şimdi KAÇ!": "Lawanmu ancang-ancang dan lingkarannya berubah EMAS! HINDARI sekarang!",
  "Kaçtın! Kontra penceresi açık, kontra vuruşlar çift hasar yapar. Hemen DİREKT!": "Kamu menghindar! Jendela serangan balik terbuka dan serangan balik memberi kerusakan ganda. CROSS sekarang!",
  "Güzel. Şimdi yere götür: İNDİR'e bas. Rakip ⬇️ ile dalarsa sen de KAÇ ile savun.": "Bagus. Sekarang jatuhkan: tekan TAKEDOWN. Kalau lawan menyergap dengan ⬇️, bertahan dengan HINDARI.",
  "Üsttesin! YUMRUK ile puan topla. Pozisyon çubuğu dolunca SUB dene.": "Kamu di atas! Cetak poin dengan PUKUL. Saat bar posisi penuh, coba SUB.",
  "Gerisi sende! Sarı çubuk nefesin: bitince vuruşların zayıflar. DİREKT ve TEKME rakibin hazırlığını keser.": "Sisanya terserah kamu! Bar kuning adalah napasmu: saat habis, pukulanmu melemah. CROSS dan TENDANG memotong ancang-ancang lawan.",
  "🥋 HOCA": "🥋 PELATIH",
  "👇 Parlayan düğmeye bas": "👇 Tekan tombol yang menyala",
  "Ve kırmızı köşede! Son kez… {0}!": "Dan di sudut merah! Untuk terakhir kalinya… {0}!",
