  "{0} bölüm": "{0} bab",
  "Ya da bir efsaneyi yaşa": "Atau jalani kisah seorang legenda",
  "{0}: Dublin'den çifte şampiyonluğa, rehberli 9 bölüm. Ücretsiz.": "{0}: dari Dublin menjadi juara dua kelas berat, 9 bab terpandu. Gratis.",
