  "Sıradaki bölüm: {0} ({1}). Önünde {2} bölüm daha var.": "Bab berikutnya: {0} ({1}). {2} bab lagi di depan.",
  "{0} hikâyesine kaldığın yerden devam et:": "Lanjutkan kisah {0} dari tempat kamu berhenti:",
  "Paket almadan da bu kariyere normal devam edebilirsin; yalnızca bölüm hedefleri ilerlemez.": "Kamu bisa terus memainkan karier ini tanpa paket; hanya target bab yang tak akan maju.",
  "SIRADAKİ EFSANE": "LEGENDA BERIKUTNYA",
  "ŞAMPİYONSUN. SIRADA EFSANELER VAR": "KAMU JUARA. BERIKUTNYA PARA LEGENDA",
  "{0} kemeri aldıktan sonra kadın MMA'sını dünyaya tanıttı. Onun yolunu bölüm bölüm yaşa.": "Setelah meraih sabuk, {0} membawa MMA wanita ke dunia. Jalani perjalanannya bab demi bab.",
  "{0} bu kemeri 29-0'lık yenilmez bir rekorla taşıdı. Onun yolunu bölüm bölüm yaşa.": "{0} membawa sabuk ini dengan rekor tak terkalahkan 29-0. Jalani perjalanannya bab demi bab.",
  "İstersen önce menüdeki Efsane Yolları'ndan her efsanenin 1. bölümünü ücretsiz dene.": "Kamu bisa mencoba bab 1 setiap legenda secara gratis di Jalan Legenda di menu.",
