  "🔒 {0} hikâyesinin devamı Efsaneler Paketi'nde. Kariyerine normal devam edebilirsin.": "🔒 Sisa kisah {0} ada di Paket Legenda. Kamu bisa terus memainkan kariermu seperti biasa.",
  "📖 EFSANE YOLU DEVAM EDİYOR: Bölüm {0}.": "📖 JALAN LEGENDA BERLANJUT: Bab {0}.",
