  "Altın Seri ve Şampiyon çerçevesi": "Seri Emas dan bingkai Juara",
  "Şampiyon ol · {0}": "Jadi Juara · {0}",
  "BUGÜN 3 REKLAM İZLEDİN": "KAMU SUDAH MENONTON 3 IKLAN HARI INI",
  "Şampiyon Paketi ile bütün ödüller reklamsız ve anında gelir. Tek seferlik alım, abonelik yok.": "Dengan Paket Juara setiap hadiah datang instan, tanpa iklan. Sekali beli, tanpa langganan.",
  "BÜTÜN YUVALAR DOLU": "SEMUA SLOT PENUH",
  "Şampiyon Paketi ile 5 kariyer yuvası: yeni bir hikâyeye başlamak için eskisini silmen gerekmez.": "Paket Juara memberimu 5 slot karier: tak perlu menghapus kisah lama untuk memulai yang baru.",
  "BİR ŞAMPİYONA YAKIŞIR PAKET": "PAKET YANG PANTAS UNTUK JUARA",
  "Kemeri kazandın. Şampiyon Paketi ile oyunun bütün ekstralarını aç.": "Kamu meraih sabuk. Buka semua ekstra game dengan Paket Juara.",
  "👑 Şampiyon Paketi ile reklamsız, anında": "👑 Tanpa iklan dan instan dengan Paket Juara",
  "👑 ŞAMPİYON PAKETİ": "👑 PAKET JUARA",
  "İstediğin iki dövüşçü, istediğin sıklet, istediğin kadar maç. Kendi efsanelerini de efsanelere karşı dövüştür.": "Dua petarung mana pun, kelas berat mana pun, laga sebanyak yang kamu mau. Hadapkan legenda-legendamu sendiri dengan para legenda juga.",
  "Hayalî Maç Stüdyosu": "Studio Laga Impian",
  "Rövanş": "Laga ulang",
  "Yeni eşleşme": "Duel baru",
  "Hayalî Maçlar'a dön": "Kembali ke Laga Impian",
  "HAYALÎ MAÇ STÜDYOSU": "STUDIO LAGA IMPIAN",
  "Kimi yöneteceksin?": "Siapa yang akan kamu kendalikan?",
  "Rakibini seç.": "Pilih lawanmu.",
  "Kırmızı köşe": "Sudut merah",
  "Mavi köşe": "Sudut biru",
  "Emekli olan dövüşçülerini emeklilik ekranından Efsanelerim'e ekleyebilirsin; burada efsanelere karşı dövüşürler.": "Kamu bisa menambahkan petarungmu yang sudah pensiun ke Legendaku dari layar pensiun; di sini mereka melawan para legenda.",
  "⭐ Efsanem": "⭐ Legendaku",
  "Rakibi değiştir": "Ganti lawan",
  "Zirvedeki halleriyle · 5 raunt": "Di masa puncak · 5 ronde",
  "{0} vs {1}": "{0} vs {1}",
  "İstediğin iki dövüşçü, istediğin sıklet, sınırsız maç. Kendi efsanelerin de burada.": "Dua petarung mana pun, kelas berat mana pun, laga tanpa batas. Legenda-legendamu sendiri juga ada di sini.",
  "⭐ Efsanelerinde · Hayalî Maç Stüdyosu'nda dövüşebilir": "⭐ Di Legendaku · bisa bertarung di Studio Laga Impian",
  "Efsanelerim dolu. 👑 Şampiyon Paketi ile 10 efsane.": "Legendaku penuh. 👑 10 legenda dengan Paket Juara.",
  "⭐ Efsanelerime ekle (Hayalî Maç Stüdyosu)": "⭐ Tambahkan ke Legendaku (Studio Laga Impian)",
  "⭐ EFSANELERİM": "⭐ LEGENDAKU",
  "{0} zirvedeki haliyle kaydedilsin; Hayalî Maç Stüdyosu'nda Conor'a, Khabir'e ve diğer efsanelere karşı dövüşsün.": "Simpan {0} di masa puncaknya dan kirim melawan Conor, Khabir, dan legenda lainnya di Studio Laga Impian.",
  "✓ Efsanelerinde": "✓ Di Legendaku",
  "Efsanelerim dolu ({0}/{1}). Şampiyon Paketi ile 10 efsane kaydedebilirsin ya da eskisinin yerine kaydedebilirsin.": "Legendaku penuh ({0}/{1}). Simpan hingga 10 legenda dengan Paket Juara, atau timpa yang lama.",
