  "Sezon tamamlandı!": "Musim selesai!",
  "Sonraki basamak: {0}/{1} puan": "Tingkat berikutnya: {0}/{1} poin",
  "Puan: maç +{0}, galibiyet +{1}, bitiriş +{2}, Günün Dövüşü +{3}, Hayalî Maç +{4}, efsane bölümü +{5}": "Poin: laga +{0}, menang +{1}, finish +{2}, Laga Harian +{3}, Laga Impian +{4}, bab legenda +{5}",
  "👑 ŞAMPİYON SIRASI": "👑 JALUR JUARA",
  "Şampiyon Paketi ile her sezon 6 ödül daha: efsanevi sezon şortu, kemer, giriş efekti… Ulaştığın basamakların ödülleri hemen açılır.": "Dengan Paket Juara, 6 hadiah tambahan setiap musim: celana musim legendaris, sabuk, efek walkout… Hadiah untuk tingkat yang sudah kamu capai langsung terbuka.",
  "Her ay yeni sezon, yeni tema. Sezon bitince alınmayan ödüller kaybolur; aldıkların dolabında kalır.": "Musim dan tema baru setiap bulan. Hadiah yang belum diklaim hilang saat musim berakhir; yang kamu klaim tetap di lokermu.",
  "Sezon Kemeri": "Sabuk Musim",
