  "O gece bir türlü aklından çıkmadı. Boyun kilidi, susan salon, kafesin üstünden atlayanlar.": "Malam itu tak pernah hilang dari pikiranmu. Neck crank, arena yang hening, orang-orang yang melompati kandang.",
  "Ama ya her şey başka türlü olsaydı? Ya rövanş gerçekten yapılsaydı?": "Tapi bagaimana kalau semuanya berjalan berbeda? Bagaimana kalau laga ulang benar-benar terjadi?",
  "Khabir Nurmagaliev hâlâ kemerin sahibi. Bu kez onu ayakta tutacak, mesafeyi sen belirleyeceksin.": "Khabir Nurmagaliev masih memegang sabuk. Kali ini kamu akan membuatnya tetap berdiri dan mengendalikan jarak.",
  "Khabir Nurmagaliev'i yen": "Kalahkan Khabir Nurmagaliev",
  "Hafif sıklete dön: Nurmagaliev kemerin sahibi olarak orada bekliyor.": "Kembali ke kelas ringan: Nurmagaliev menunggu di sana sebagai juara.",
  "Hafif sıklet kemerini al": "Menangkan sabuk kelas ringan",
  "Rövanş PPV payı": "Bagi hasil PPV laga ulang",
  "🔀 Tarih yeniden yazıldı: rövanşı kazanan sensin.": "🔀 Sejarah ditulis ulang: kamu memenangkan laga ulang.",
  "Hiç Sorun Çıkarmasaydı": "Andai Dia Menjauhi Masalah",
  "Cezalar, kayıp yıllar, manşetlere düşen gece yarısı haberleri… Hiçbiri yaşanmasaydı?": "Skorsing, tahun-tahun yang hilang, berita tengah malam… Bagaimana kalau semua itu tak pernah terjadi?",
  "Bu kez erken yatıyorsun, salona ilk sen giriyorsun, telefonunu kapatıyorsun.": "Kali ini kamu tidur cepat, jadi yang pertama di sasana, dan mematikan ponsel.",
