  "Bu kategoride dövüşçün yok. Önce bir kariyer başlat.": "Kamu tak punya petarung di divisi ini. Mulai karier dulu.",
  "Arkadaşının dövüşçüsü yapay zekâyla karşına çıkar. Sen de kodunu paylaş, seninkiyle dövüşsünler.": "Petarung temanmu masuk melawanmu, dikendalikan AI. Bagikan juga kodemu agar dia bisa melawan petarungmu.",
  "Hayalet Maç": "Laga Hantu",
  "SENİN KODUN": "KODEMU",
  "Kod paylaşmak için önce bir kariyer başlat.": "Mulai karier dulu untuk membagikan kode.",
  "{0} ile meydan oku": "Tantang dengan {0}",
