  "Henüz hayaletin yok. Arkadaşlarından kod iste ya da kendi kodunu paylaş.": "Belum ada hantu. Minta kode dari teman atau bagikan kodemu.",
  "Karnen: {0}-{1}-{2}": "Rekormu: {0}-{1}-{2}",
