  "Kartın zirvesindeki maçları tahmin et. Doğru kazanan para kazandırır; favori olmayanı bilmek daha değerli. Bitiriş ya da kararı da bilirsen ek ödül.": "Prediksi laga-laga teratas di kartu. Menebak pemenang dengan benar memberi uang, dan menebak non-unggulan nilainya lebih besar. Tebak juga finish atau angka dengan benar untuk bonus.",
