  "{0} bacaklara daldı, {1} sprawl ile savundu.": "{0} menyergap kaki, {1} melakukan sprawl untuk bertahan.",
  "{0} rakibini yere indirdi, üstten kontrol ediyor.": "{0} menjatuhkan lawan dan mengendalikan dari atas.",
