  "Ortada sert bir değişim, ikisi de vurdu.": "Adu pukulan keras di tengah, keduanya kena.",
  "💥 {0} yere düştü!": "💥 {0} jatuh!",
  "Bitti! {0} ayağa kalkamadı, hakem hemen araya girdi.": "Selesai! {0} tak bisa bangkit dan wasit langsung masuk.",
  "Maçı durdur": "Hentikan laga",
  "Devam ettir": "Biarkan berlanjut",
  "Kollarını kaldırmıyor, gözleri boşlukta.": "Dia tak mengangkat tangan, matanya kosong.",
  "Yumruklara hiç tepki vermiyor, yüzü açık.": "Tak bereaksi terhadap pukulan, wajahnya terbuka lebar.",
  "Elleriyle kapatıyor ama karşılık vermiyor.": "Menutupi diri dengan tangan tapi tak membalas.",
  "Dizlerinin üstünde, başını korumaya çalışıyor.": "Berlutut, mencoba melindungi kepala.",
  "Bacağa sarılıp kalkmaya çalışıyor.": "Meraih kaki dan mencoba berdiri.",
