  "Aklınla dövüşüyorsun. Rakip seni daha geç okur, köşen zaafları daha çabuk bulur.": "Kamu bertarung dengan kepala. Lawan lebih lambat membacamu dan sudutmu lebih cepat menemukan kelemahan.",
