  "Elinde tek bir sokak dövüşçüsü ve kirası ödenmemiş bir bodrum ofis var. Her şey sana bağlı.": "Yang kamu punya hanya satu petarung jalanan dan kantor ruang bawah tanah dengan sewa yang belum dibayar. Semuanya ada di tanganmu.",
  "Tek yıldız": "Satu bintang",
  "Kadronda bir UCC şampiyonu var, ama sözleşmesi bitmek üzere ve rakip ajanslar kapıda. Onu kaybetme.": "Kamu punya juara UCC di roster, tapi kontraknya hampir habis dan agensi rival sudah di depan pintu. Jangan sampai kehilangan dia.",
  "Batık ajansı kurtar": "Selamatkan agensi yang tenggelam",
  "Önceki menajerden borç ve sana küskün üç dövüşçü devraldın. Bir yılda borcu kapat.": "Kamu mewarisi utang dari manajer sebelumnya dan tiga petarung yang membencimu. Lunasi utangnya dalam setahun.",
  "Yurt dışı yetenekleri": "Bakat dari luar negeri",
  "Brezilya ve Dağıstan'dan iki genç yetenek getirdin. Vize, dil ve gurbet sorunlarıyla yıldız yap.": "Kamu membawa dua bakat muda dari Brasil dan Dagestan. Jadikan mereka bintang melewati urusan visa, kendala bahasa, dan rindu rumah.",
  "İlk yılında bir dövüşçünü bölgesel lige taşı.": "Bawa salah satu petarungmu ke liga regional di tahun pertama.",
  "Abi, otoparktaki dövüşleri bırakıp gerçek bir kafese çıkmak istiyorum. Sana güveniyorum. Beni bir yere götür.": "Bang, aku mau berhenti dari laga di parkiran dan masuk kandang sungguhan. Aku percaya padamu. Bawa aku ke suatu tempat.",
  "{0} ile yeni sözleşme imzala, onu rakip ajanslara kaptırma.": "Tanda tangani kontrak baru dengan {0} dan jangan sampai dia direbut agensi rival.",
  "Sözleşmem bir maç sonra bitiyor. Telefonum susmuyor, herkes beni istiyor. Sen beni neden tutmalıyım, onu düşünüyorum.": "Kontrakku habis setelah satu laga lagi. Teleponku tak berhenti berdering, semua orang menginginkanku. Aku sedang berpikir kenapa aku harus mempertahankanmu.",
  "Bir yıl içinde borcu kapat (para sıfırın üstüne çıksın).": "Lunasi utang dalam setahun (buat kasmu di atas nol).",
  "Ajansınızın {0} borcu bulunmaktadır. Kira ödemeleri devam ettikçe borç büyüyecektir.": "Agensimu berutang {0}. Utangnya akan bertambah selama sewa terus jatuh tempo.",
  "Eski menajer paramızı yedi. Sen farklı mısın, göreceğiz.": "Manajer lama memakan uang kami. Kita lihat apakah kamu berbeda.",
  "İki yeteneğinden birini büyük lige taşı.": "Bawa salah satu dari dua bakatmu ke liga besar.",
  "Burası çok soğuk, abi. Annem her gün arıyor. Ama söz verdim, kemerle döneceğim.": "Di sini dingin sekali, bang. Ibuku menelepon setiap hari. Tapi aku sudah berjanji, aku pulang membawa sabuk.",
  "Ofis dolu. Yeni dövüşçü için ofisi büyüt ya da birini bırak.": "Kantor penuh. Tingkatkan kantor untuk petarung baru atau lepas seseorang.",
  "İmza parası için yeterli paran yok.": "Uangmu tidak cukup untuk biaya rekrut.",
