  "✍️ {0} ajansına katıldı!": "✍️ {0} bergabung dengan agensi!",
  "Hafta {0}: {1} ile yollar ayrıldı.": "Minggu {0}: berpisah dengan {1}.",
  "Hafta {0}: Çıkış maddesi işledi, {1} bedelsiz ayrıldı.": "Minggu {0}: klausul keluar berlaku, {1} pergi tanpa biaya.",
  "Hafta {0}: {1} sözleşmesini {2} bedelle feshetti.": "Minggu {0}: {1} membeli kontraknya seharga {2}.",
  "{0}! Rüya gibi. Bunu sana borçluyum.": "{0}! Seperti mimpi. Aku berutang ini padamu.",
  "Annemi aradım, ağladı. {0} sözleşmesi, inanamıyorum.": "Aku menelepon ibuku, dia menangis. Kontrak {0}, aku tak percaya.",
  "Daha yeni başlıyoruz. {0}'de herkes adımı öğrenecek.": "Kita baru saja mulai. Semua orang di {0} akan tahu namaku.",
  "Hafta {0}: {1} için {2} ile {3} maçlık sözleşme ({4}/maç).": "Minggu {0}: kontrak {3} laga untuk {1} dengan {2} ({4}/laga).",
  "📝 {0} artık {1} dövüşçüsü.": "📝 {0} kini petarung {1}.",
  "🗓️ {0} – {1} maçı {2}. haftada.": "🗓️ {0} vs {1} di minggu {2}.",
  "{0}: “Teklifimiz ortada. Dinliyoruz.”": "{0}: “Tawaran kami sudah di meja. Kami mendengarkan.”",
  "{0}: “Son teklifimiz {1}. İmzala ya da yolumuza bakalım.”": "{0}: “Tawaran terakhir kami {1}. Tanda tangan atau kita berpisah jalan.”",
  "{0}: “Tamam, {1} olsun.”": "{0}: “Baik, {1}.”",
  "{0}: “Peki. Maç başı {1}.”": "{0}: “Baiklah. {1} per laga.”",
  "{0}: “Zorluyorsun ama olur: {1}.”": "{0}: “Kamu memaksa, tapi oke: {1}.”",
  "{0}: “Bütçeyi zorluyorsun. {1} yapabiliriz.”": "{0}: “Kamu meregangkan anggaran. Kami bisa {1}.”",
  "{0}: “Kazanırsa hak eder. Bonus {1}.”": "{0}: “Kalau dia menang, dia pantas. Bonus {1}.”",
  "{0}: “Münhasırlık mı? Seve seve. Ücrete %15 ekliyoruz.”": "{0}: “Eksklusivitas? Dengan senang hati. Kami tambah 15% ke bayaran.”",
  "{0}: “{1}, kabul. Sözleşmeye yazıyoruz.”": "{0}: “{1}, diterima. Kami tulis di kontrak.”",
  "{0}: “Çıkış maddesi mi? Dövüşçüne yatırım yapıyoruz, kaçmasına izin vermeyiz.”": "{0}: “Klausul keluar? Kami berinvestasi pada petarungmu, kami tak akan membiarkannya pergi.”",
  "{0}: “{1} olmaz. Başka bir şey?”": "{0}: “{1} kami tolak. Ada lagi?”",
  "nakavt": "knockout",
