  "{0} ilk dakikadan merkezi aldı.": "{0} menguasai tengah sejak menit pertama.",
  "{0} rakibinin ritmini çözdü.": "{0} memecah ritme lawan.",
  "{0} zor anlardan sakin çıktı.": "{0} tetap tenang di momen-momen sulit.",
