  "İkisi de “Varım” dedi. Kararı onlar verdi; güvenleri sağlam. Maç {0}. haftada.": "Keduanya bilang “Aku ikut.” Itu keputusan mereka, jadi kepercayaan mereka utuh. Laganya di minggu {0}.",
