  "Masada en sert sensin: organizasyonlar sana daha çok öder. Ama dövüşçülerin sana kolay ısınmaz.": "Kamu yang paling keras di meja negosiasi: promosi membayarmu lebih. Tapi petarungmu tak mudah dekat denganmu.",
  "Baba": "Godfather",
  "Dövüşçülerin aileden biri: kötü kararlarını daha kolay affeder, rakip ajanslara kulak asmazlar.": "Petarungmu adalah keluarga: mereka lebih mudah memaafkan keputusan burukmu dan mengabaikan agensi rival.",
  "Ham yeteneği şekillendirirsin: gençler senin elinde daha hızlı gelişir, gözün daha keskindir.": "Kamu membentuk bakat mentah: petarung muda berkembang lebih cepat di tanganmu, dan matamu lebih tajam.",
