  "Kameralar açık, salon dolu. {0} mikrofonu aldı, gözü {1} üzerinde. Ne konuşsun?": "Kamera merekam, ruangan penuh. {0} mengambil mikrofon, menatap {1}. Apa yang harus dia katakan?",
