  "{0} · maç gecesi": "{0} · malam pertarungan",
  "Soyunma odasındayız. Rakip {0}: {1}. Raunt arasında köşeye tek bir not iletebilirsin. Ne diyelim?": "Kami di ruang ganti. Lawannya {0}: {1}. Kamu bisa mengirim satu catatan ke sudut di antara ronde. Apa yang kita katakan?",
