  "Baskı kur, nefesini kes.": "Tekan dia, habiskan napasnya.",
  "Salon karıştı, klip milyonlarca izlendi. Bilet satışları uçtu, ama rakip artık çok hırslı.": "Ruangan meledak, klipnya ditonton jutaan kali. Penjualan tiket melonjak, tapi lawan kini terbakar.",
  "Manşetlerdesiniz. Rakip kampı “onu susturacağız” dedi.": "Kamu jadi berita utama. Kamp lawan bilang “kami akan membungkamnya.”",
  "Patron memnun: “Böyle dövüşçüleri severiz.”": "Bos senang: “Kami suka petarung seperti itu.”",
  "Kısa cevaplar, soğuk bakışlar. Dövüşçün tamamen maça odaklı.": "Jawaban singkat, tatapan dingin. Petarungmu sepenuhnya fokus pada laga.",
  "Araya girdin, kriz büyümedi. Fotoğraflar yine de olay oldu.": "Kamu turun tangan dan krisis tak meningkat. Fotonya tetap viral.",
  "Şov oldu, ama komisyon {0} para cezası kesti.": "Itu pertunjukan, tapi komisi mendendanya {0}.",
  "Görüntüler her yerde. Herkes cumartesiyi bekliyor.": "Rekamannya ada di mana-mana. Semua orang menunggu Sabtu.",
  "Omzundan tutup kenara çektin. Gözleri hâlâ yanıyor, ama artık kontrol sende.": "Kamu meraih bahunya dan menariknya ke samping. Matanya masih membara, tapi kamu yang mengendalikan sekarang.",
  "Köşe başını salladı: “Tam düşündüğümüz şey.”": "Sudut mengangguk: “Persis yang kami pikirkan.”",
  "Antrenör notu okuyup gülümsedi. Plan net.": "Pelatih membaca catatan itu dan tersenyum. Rencananya jelas.",
  "Antrenör kaşlarını çattı: “Onunla yerde mi? Emin misin?”": "Pelatih mengernyit: “Di bawah bersama dia? Kamu yakin?”",
  "Köşe notu aldı. Fena bir plan değil, ama en iyisi de değil.": "Sudut menerima catatannya. Rencana tidak buruk, tapi juga bukan yang terbaik.",
