  "Büyük oynayalım: {0} karşısında {1} ({2}). Sabit ücret mi, yoksa PPV satışlarından pay mı? Teklifler sekmesinde.": "Ayo main besar: {1} ({2}) melawan {0}. Bayaran tetap atau bagian dari penjualan PPV? Ada di tab Tawaran.",
  "Paylaşım patladı! Telefonun çalıyor: süper dövüş teklifi geldi.": "Postingannya meledak! Teleponmu berdering: tawaran laga super masuk.",
  "Paylaşım gündem oldu. Şöhreti arttı.": "Postingannya viral. Ketenarannya naik.",
  "Video yayıldı, yorumlar ikiye bölündü. Ama herkes onu konuşuyor.": "Videonya menyebar, kolom komentar terbelah. Tapi semua orang membicarakannya.",
  "Son şans": "Kesempatan terakhir",
  "Kızı için kemer": "Sabuk untuk putrinya",
  "Sokaktan gelen dâhi": "Jenius dari jalanan",
  "Sana açık konuşayım: {0} yaşındayım. İki yıl içinde kemer yoksa eldivenleri asacağım. Bu benim son şansım.": "Aku terus terang saja: usiaku {0}. Kalau tak ada sabuk dalam dua tahun, aku gantung sarung tangan. Ini kesempatan terakhirku.",
  "Kızım her gece soruyor: “Baba, kemer ne zaman?” Ona söz verdim. Bir yıl içinde bir kemer getireceğim, hangi ligde olursa olsun.": "Putriku bertanya setiap malam: “Ayah, kapan sabuknya?” Aku sudah berjanji. Aku akan membawa pulang sabuk dalam setahun, di liga mana pun.",
  "Herkes beni bitti sanıyordu. Yaşlı kurt hâlâ ısırıyor, değil mi?": "Semua orang mengira aku tamat. Serigala tua masih bisa menggigit, kan?",
  "Kızım son maçımı okulda arkadaşlarına izletmiş. Öğretmeni aradı, gülmekten öldük.": "Putriku menunjukkan laga terakhirku ke teman-temannya di sekolah. Gurunya menelepon, kami tak berhenti tertawa.",
  "Yaptık. Kimse inanmazken sen inandın. Bu kemer ikimizin, ortak.": "Kita berhasil. Kamu percaya saat tak ada yang percaya. Sabuk ini milik kita berdua, partner.",
  "Kemeri kızımın beline taktım. Ona bol geldi, ama gözleri… Bunu sana borçluyum.": "Kupasang sabuk itu di pinggang putriku. Terlalu besar untuknya, tapi matanya… Aku berutang ini padamu.",
  "📖 Hikâye tamamlandı: {0} ({1}) · itibar +5": "📖 Kisah selesai: {0} ({1}) · reputasi +5",
  "Hafta {0}: 📖 {1}: “{2}” hikâyesi mutlu sonla bitti.": "Minggu {0}: 📖 {1}: kisah “{2}” berakhir bahagia.",
  "Söz sözdür. Eldivenleri asıyorum. Kemer olmadı, ama yanımda sen vardın. Teşekkürler.": "Janji adalah janji. Aku gantung sarung tangan. Tanpa sabuk, tapi kamu ada di sisiku. Terima kasih.",
  "📖 {0} kemersiz veda etti.": "📖 {0} berpamitan tanpa sabuk.",
  "Bir yıl geçti. Kızım artık sormuyor. Bu daha kötü.": "Setahun berlalu. Putriku tak bertanya lagi. Itu lebih buruk.",
  "{0} için antrenörü": "Pelatih {0}",
  "{0} yine antrenmana gelmedi. Mahalledeki eski arkadaşlarıyla takılıyor, evde kavga bitmiyor. Bu çocuk kaybolacak.": "{0} bolos latihan lagi. Bergaul dengan teman lama di kampung, ribut terus di rumah. Anak ini akan tersesat.",
  "Salonun yanına oda tut, oraya taşınsın ({0}).": "Sewa kamar di sebelah sasana, suruh dia pindah ke sana ({0}).",
  "Oturup ailesiyle konuşacağım.": "Aku akan duduk dan bicara dengan keluarganya.",
  "Bu onun özel hayatı, karışmam.": "Itu kehidupan pribadinya, aku tak akan ikut campur.",
  "Sen olmasan o sokaklarda kaybolup giderdim. Şimdi büyük ligdeyim. Annem ilk kez maçımı izleyecek.": "Tanpamu aku sudah tersesat di jalanan itu. Sekarang aku di liga besar. Ibuku akan menontonku bertarung untuk pertama kalinya.",
  "📖 {0} sokaktan büyük lige uzandı · itibar +4": "📖 {0} berhasil dari jalanan ke liga besar · reputasi +4",
  "Yeni odasına taşındı. İlk hafta her sabah ilk o geldi. (Güç +2)": "Pindah ke kamar baru. Di minggu pertama, yang pertama datang setiap pagi. (Kekuatan +2)",
  "Annesi ağladı, babası elini sıktı. Ev sakinleşti, çocuk salona döndü.": "Ibunya menangis, ayahnya menjabat tanganmu. Rumah tenang, anak itu kembali ke sasana.",
  "Babası kapıyı yüzüne kapattı. Çocuk arada kaldı.": "Ayahnya membanting pintu di depan mukamu. Anak itu terjepit di tengah.",
  "İki hafta sonra bir gece kavgasından karakola düştü. Eskisi gibi değil artık.": "Dua minggu kemudian, perkelahian malam membuatnya masuk kantor polisi. Dia tak lagi sama.",
  "Bir süre kayboldu, sonra kendiliğinden döndü. Şanslısın.": "Dia menghilang sebentar, lalu kembali sendiri. Kamu beruntung.",
