  "Bu sefer kafese sen çıkmıyorsun. Dövüşçülerin kariyeri, parası ve sağlığı senin telefonunda.": "Kali ini bukan kamu yang masuk kandang. Karier, uang, dan kesehatan petarungmu ada di ponselmu.",
  "Telefonun hiç susmaz: dövüşçüler, patronlar, gazeteciler ve rakip menajerler. Her cevabın bir sonucu var.": "Ponselmu tak pernah berhenti: petarung, bos, wartawan, dan manajer rival. Setiap jawaban ada konsekuensinya.",
  "Organizasyonların gizli bütçesine karşı pazarlık yap; rövanş, çıkış ve sakatlık maddeleri yıllar sonra işine yarar.": "Bernegosiasi melawan anggaran tersembunyi promosi; klausul laga ulang, keluar, dan cedera membuahkan hasil bertahun-tahun kemudian.",
  "Yetenek avına çık, gençleri komisyon pazarlığıyla imzala, rakip ajanslardan önce davran.": "Lakukan pencarian bakat, rekrut bakat muda dengan kesepakatan komisi, dan bergerak sebelum agensi rival.",
  "İki dövüşçün aynı kemere yürürse? Organizasyon onları birbirine eşlemek isteyecek.": "Bagaimana jika dua petarungmu mengejar sabuk yang sama? Promosi akan ingin mempertemukan mereka.",
  "Doktor uyarır, para çağırır. Dövüşçünün sağlığı mı, maaş günü mü?": "Dokter memperingatkan, uang memanggil. Kesehatan petarungmu atau gajinya?",
  "Bodrum kat ofisinden gökdelene: şampiyonlar çıkar, Yılın Menajeri ol.": "Dari kantor ruang bawah tanah ke gedung pencakar langit: cetak juara, jadilah Manajer Terbaik.",
