  "Hakem, Antrenör ve Menajer Modu, bütün efsaneler, reklamsız oyun ve 6 kozmetik paket.": "Mode Wasit, Pelatih, dan Manajer, semua legenda, main tanpa iklan, dan 6 paket kosmetik.",
