  "Reklamsız oyun, ödüller anında, 5 kariyer yuvası, bütün efsaneler ve Altın Seri. Hakem, Antrenör ve Menajer Modu dahil değil.": "Main tanpa iklan, hadiah instan, 5 slot karier, semua legenda, dan Seri Emas. Tidak termasuk Mode Wasit, Pelatih, dan Manajer.",
