  "Bütün modların aynı dünyada geçiyor. Kariyerindeki dövüşçülerin Menajer Modu'nda rakip olarak teklif edilir; Menajer Modu'ndaki dövüşçülerin de büyük ligde ve UCC'de kariyerinin karşısına çıkar.": "Semua modemu berbagi satu dunia. Petarung kariermu ditawarkan sebagai lawan di Mode Manajer, dan petarung Mode Manajer-mu muncul melawan kariermu di liga besar dan UCC.",
  "ÇAPRAZ MAÇ": "LINTAS MODE",
  "ÇAPRAZ MAÇLAR": "LAGA LINTAS MODE",
  "Henüz modlar arası maç yok. Büyük lige çıktıkça ve Menajer Modu'nda teklifler geldikçe dövüşçülerin karşılaşacak.": "Belum ada laga lintas mode. Saat kamu mencapai liga besar dan tawaran datang di Mode Manajer, petarung-petarungmu akan bertemu.",
