  "annem de izliyor selam": "ibuku juga nonton, hai",
  "gece 3, uyumuyorum senin yüzünden": "jam 3 pagi, tak bisa tidur gara-gara kamu",
  "bir sonraki afişi bekliyoruz": "menunggu poster berikutnya",
  "diyet ne yapıyorsun?": "kamu diet apa?",
