  "izlemeye devam 👀": "masih nonton 👀",
  "Kampın nasıl geçti? Bu maç için ne değiştirdin?": "Bagaimana kampnya? Apa yang kamu ubah untuk laga ini?",
  "“Her gün biraz daha iyi olmaya çalıştık. Gerisini kafeste göreceğiz.”": "“Kami berusaha jadi sedikit lebih baik setiap hari. Sisanya kita lihat di kandang.”",
  "“Ekibime güveniyorum. İşimizi yaptık.”": "“Aku percaya timku. Kami sudah melakukan tugas kami.”",
  "“Bu kampta onu üç kez yendim, sparringde. Cumartesi dördüncüsü.”": "“Aku mengalahkannya tiga kali di kamp ini, di sparring. Sabtu yang keempat.”",
  "“Hiç bu kadar hazır olmadım. Şanssızlığı onun.”": "“Aku belum pernah sesiap ini. Sial untuknya.”",
  "“Değişen tek şey diyetim. Özledim pideyi.”": "“Satu-satunya yang berubah adalah dietku. Aku rindu pizza.”",
  "“Hocam bağırmaktan sesini kaybetti, demek ki iyi geçti.”": "“Pelatihku sampai kehilangan suara karena berteriak, jadi lancar.”",
  "“Her şey sizin için. İyi ki varsınız.”": "“Semua ini untuk kalian. Senang kalian di sini.”",
  "“Desteğinizi hissediyorum. Sizi mahcup etmeyeceğim.”": "“Aku merasakan dukungan kalian. Aku tak akan mengecewakan.”",
  "“Tribünleri doldurun, bir şov izleyeceksiniz.”": "“Penuhi tribun, kalian akan melihat pertunjukan.”",
  "“Bayramı şimdiden hazırlayın.”": "“Mulailah siapkan pestanya sekarang.”",
  "“Bilet alanlar arkada oturmasın, önde daha çok kan var.”": "“Pemegang tiket, jangan duduk di belakang, di depan lebih banyak darah.”",
  "“Cumartesiden sonra hepinize çay benden.”": "“Setelah Sabtu, teh untuk semua aku yang traktir.”",
  "{0} senin en zayıf yanını bulduğunu söylüyor. Ne diyeceksin?": "{0} bilang dia menemukan kelemahan terbesarmu. Apa katamu?",
  "“Herkesin zayıf yanı vardır. Ben de kendiminkini çalıştım.”": "“Semua orang punya kelemahan. Aku sudah melatih punyaku.”",
  "“Bulmuşsa iyi, ben de onunkini buldum.”": "“Bagus kalau dia menemukannya, aku juga menemukan punyanya.”",
  "“Zayıf yanım mı? Onu bulmak için önce ayakta kalması lazım.”": "“Kelemahanku? Dia harus tetap berdiri dulu untuk menemukannya.”",
  "“Bulsun. Cumartesi aramaya vakti olmayacak.”": "“Biarkan saja. Dia tak akan sempat mencari Sabtu nanti.”",
  "“Zayıf yanım tatlı. Kafeste tatlı yok, sorun yok.”": "“Kelemahanku makanan manis. Tak ada makanan manis di kandang, jadi tak masalah.”",
  "“Bunu söylemesi bile bir zayıflık aslında.”": "“Mengatakan itu sudah merupakan kelemahan.”",
  "Ne zaman emekli olmayı düşünüyorsun?": "Kapan kamu berpikir untuk pensiun?",
  "“Vücudum söyleyecek. Şimdilik dinliyor.”": "“Tubuhku yang akan memberitahu. Untuk sekarang dia masih mendengarkan.”",
  "“Daha yolun başındayım gibi hissediyorum.”": "“Rasanya aku baru saja mulai.”",
  "“Bütün rekorları kırınca. Yani biraz daha var.”": "“Saat semua rekor sudah kupecahkan. Jadi masih lama.”",
  "“Rakip kalmadığında. Takvimi ona göre ayarlayın.”": "“Saat tak ada lagi lawan. Susun kalendernya berdasarkan itu.”",
  "“Emeklilik maaşı yeterse yarın. Yetmiyor, devam.”": "“Besok, kalau pensiunnya cukup. Tidak cukup, jadi aku lanjut.”",
  "“Torunum beni yenince.”": "“Saat cucuku mengalahkanku.”",
  "Bu maçtan ne kadar kazanacaksın?": "Berapa yang akan kamu hasilkan dari laga ini?",
  "“Para önemli ama kemer daha önemli.”": "“Uang itu penting, tapi sabuk lebih penting.”",
  "“Hak ettiğim kadar. Gerisi menajerin işi.”": "“Sebanyak yang pantas kudapat. Sisanya urusan manajerku.”",
  "“Yetmez. Bir sonrakinde iki katını isteyeceğim.”": "“Tidak cukup. Lain kali aku minta dua kali lipat.”",
  "“Onun bütün kariyerinde kazandığından fazla.”": "“Lebih dari yang dia hasilkan sepanjang kariernya.”",
  "“Yeni bir araba alacak kadar. Park yeri bulamayacak kadar değil.”": "“Cukup untuk beli mobil baru. Tidak cukup untuk cari parkir.”",
  "“Annem duyunca hemen fatura listesi yolladı.”": "“Ibuku dengar dan langsung mengirimiku tagihan.”",
  "Sosyal medyada {0} ile atışmanız gündem oldu. Bu iş kafeste mi bitecek?": "Saling balasmu dengan {0} di media sosial viral. Apakah ini berakhir di kandang?",
  "“Sosyal medya bir şey, kafes başka. Ben kafese bakarım.”": "“Media sosial satu hal, kandang hal lain. Aku fokus ke kandang.”",
  "“Klavye arkasında herkes cesur. Cumartesi göreceğiz.”": "“Semua orang berani di balik keyboard. Kita lihat Sabtu nanti.”",
  "“Paylaşımlarını silmesi için cumartesiye kadar vakti var.”": "“Dia punya waktu sampai Sabtu untuk menghapus postingannya.”",
  "“Yorumları kapatsın, maçtan sonra çok yorum gelecek.”": "“Sebaiknya dia matikan komentar, akan banyak setelah laga.”",
  "“Takipçi sayıma bakın, cevabım orada.”": "“Lihat jumlah pengikutku, itu jawabanku.”",
  "“Ona bir emoji yolladım: 🪦.”": "“Aku mengiriminya emoji: 🪦.”",
  "Arka sıradaki eski bir şampiyon onaylarcasına başını salladı.": "Seorang mantan juara di barisan belakang mengangguk setuju.",
  "Sakin bir cevap. Tribünlerde saygılı bir alkış koptu.": "Jawaban tenang. Tepuk tangan penuh hormat dari tribun.",
  "Moderatör mikrofonu almaya çalıştı ama geç kaldı.": "Moderator mencoba merebut mikrofon tapi terlambat.",
  "Bahis siteleri oranları anında güncelledi.": "Situs taruhan langsung memperbarui odds.",
  "Rakibin köşesindeki hoca bile güldü, sonra kendini tuttu.": "Bahkan pelatih di sudut rival tertawa, lalu menahan diri.",
  "Bu cevap birkaç dakika içinde milyonlarca izlenmeye gidiyor.": "Jawaban ini akan ditonton jutaan kali dalam hitungan menit.",
  "{0}: “Böyle konuşan herkes kafeste başka biri olur.”": "{0}: “Semua yang bicara seperti itu jadi orang lain di kandang.”",
  "{0} yanındakine döndü: “Gördün mü, korkuyor.”": "{0} menoleh ke timnya: “Lihat? Dia takut.”",
  "{0} ayağa kalktı, güvenlik araya girdi.": "{0} berdiri, petugas keamanan turun tangan.",
  "{0}: “Bu cümleyi çerçeveletip duvarına as, son kez söylüyorsun.”": "{0}: “Bingkai kalimat itu dan gantung di dindingmu, itu terakhir kalinya kamu mengatakannya.”",
  "{0}: “Gülmek serbest, cumartesi ağlamak da.”": "{0}: “Tertawalah selagi bisa, Sabtu nanti menangis juga boleh.”",
  "{0} kahkahayı bastıramadı, salon ikisine birden güldü.": "{0} tak bisa menahan tawa, ruangan menertawakan mereka berdua.",
  "{0} geri çekilirken mırıldandı: “Cumartesi göreceğiz.”": "{0} bergumam sambil mundur: “Kita lihat Sabtu nanti.”",
  "{0} kameraya döndü: “Bakışlar dövüşmez.”": "{0} menoleh ke kamera: “Tatapan tidak bertarung.”",
  "{0} sinirle omuz silkti, köşesine yürüdü.": "{0} mengangkat bahu dengan marah dan berjalan ke sudutnya.",
  "{0}: “Bu gece kazandın, cumartesi benim.”": "{0}: “Kamu menang malam ini, Sabtu milikku.”",
  "{0} kameralara döndü: “Gördünüz mü, şimdiden korkuyor.”": "{0} menoleh ke kamera: “Lihat itu? Dia sudah takut.”",
  "{0} giderken arkasından seslendi: “Cumartesi daha kötü olacak!”": "{0} berseru saat pergi: “Sabtu akan lebih buruk!”",
  "{0} el sallayıp güldü: “Tatlı rüyalar.”": "{0} melambai dan tertawa: “Mimpi indah.”",
  "{0}: “Bu daha ısınma turu.”": "{0}: “Itu baru pemanasan.”",
  "{0}: “Saygı var. Ama cumartesi kardeşlik yok.”": "{0}: “Ada respek. Tapi tak ada persaudaraan Sabtu nanti.”",
  "{0} başını salladı, iki taraf da sessizce ayrıldı.": "{0} mengangguk, kedua pihak berpisah dalam diam.",
  "{0}: “Güzel bir maç olacak. Kazanan ben olacağım.”": "{0}: “Ini akan jadi laga bagus. Pemenangnya aku.”",
