  "İleri yürü, rakibi iplere daya. Çok hasar, çok yorgunluk.": "Maju dan tekan dia ke tali. Banyak kerusakan, banyak kelelahan.",
  "Rakip gelsin, açığını kontra yumrukla cezalandır.": "Biarkan dia datang dan hukum celahnya dengan serangan balik.",
  "Jab ve ayak oyunu": "Jab dan footwork",
  "Jab ile puan topla, ringin ortasında dön, köşeye sıkışma.": "Cetak poin dengan jab, berputar di tengah, jangan sampai terjebak di sudut.",
