  "Bacağa dal": "Sergap kaki",
  "Tek ya da çift bacak; indirme puanını al.": "Single atau double leg; ambil poin takedown.",
  "Kol bağla, belden kavra; suplex ve çevirme.": "Ikat satu lengan, kunci pinggang; suplex dan balik.",
  "Dalışını kes, arkasına dön; tuş fırsatını bekle.": "Hentikan sergapannya, berputar ke belakang; tunggu kuncian bahu.",
  "Jabı unutma, her şey jabla başlar.": "Jangan lupa jab, semuanya dimulai dengan jab.",
  "Çeneni göğsüne göm, ellerini yukarıda tut.": "Dagu turun, tangan naik.",
  "Gövdeye vur, kafa kendiliğinden gelir.": "Serang tubuh, kepala akan mengikuti.",
  "İplere yaslanma, ringin ortasında kal.": "Jangan bersandar ke tali, tetap di tengah ring.",
  "Vur ve çık; orada durma.": "Pukul dan bergerak; jangan diam di situ.",
  "Tekmesini yakala, süpür!": "Tangkap tendangannya dan sapu dia!",
  "Klinçte ensesini bırakma, dizle!": "Jangan lepaskan lehernya di clinch, lutut dia!",
  "Ön bacağına low kick, o bacağı öldür.": "Tendangan rendah ke kaki depannya, matikan kaki itu.",
  "Dirsek mesafesi açıldığında gönder.": "Saat jarak siku terbuka, lempar.",
  "Teep ile mesafeyi sen belirle.": "Atur jarak dengan teep-mu.",
  "Önce pozisyon, sonra kilit!": "Posisi dulu, baru submission!",
  "Sırtını mindere verme, kalçanı kaçır!": "Jangan berikan punggungmu di matras, gerakkan pinggulmu!",
  "Kolunu dışarıda bırakıyor, kimura'ya bak.": "Dia membiarkan lengannya keluar, incar kimura.",
  "Ağırlığını ver, nefes aldırma.": "Taruh beratmu di atasnya, jangan biarkan dia bernapas.",
  "Ayağa kalkmasına izin verme.": "Jangan biarkan dia berdiri.",
  "Bacaklarına dal, puan orada!": "Sergap kakinya, poinnya di sana!",
  "Köprü kur, sırtını yere değdirme!": "Bridge! Jangan biarkan punggungmu menyentuh matras!",
  "Kafa pozisyonunu kaybetme.": "Jangan kehilangan posisi kepalamu.",
  "Kolunu bağla, belinden kavra!": "Ikat lengannya, kunci pinggangnya!",
  "Çevir onu! Tuşa bir adım kaldı.": "Balik dia! Kamu selangkah lagi dari kuncian bahu.",
  "SAYIM: {0}": "HITUNGAN: {0}",
