  "{A} rakibini iplere dayıyor ve sol-sağ-sol hook serisini boşaltıyor!": "{A} menekan lawannya ke tali dan melepaskan rentetan hook kiri-kanan-kiri!",
  "{A} köşeye sıkıştırdı; ağır bir sağ el yüze temiz iniyor!": "{A} menjebaknya di sudut; tangan kanan yang berat mendarat telak!",
  "{A} içeri girip aparkatla başlayan bir kombinasyon bağlıyor.": "{A} melangkah masuk dan merangkai kombinasi yang dimulai dengan uppercut.",
  "{A} başını eğip sıyrılıyor, rakip boşluğa düşüyor ve kısa bir sol hook yiyor.": "{A} menyelinap ke bawah, lawan jatuh ke ruang kosong dan terkena hook kiri pendek.",
  "{A} ringin ortasında dönüp jab-kros ile puan topluyor.": "{A} berputar di tengah ring dan mencetak jab-cross.",
  "{A} ayak oyunuyla açı alıp çift jab yapıştırıyor ve çıkıyor.": "{A} menemukan sudut dengan footwork, mendaratkan double jab lalu keluar.",
  "{A} uzun jabıyla rakibin atağını daha başlamadan kesiyor.": "{A} mematikan serangan lawan sebelum dimulai dengan jab panjang.",
  "{A} ileri yürüyor; yumruk serisini sert bir orta tekmeyle bağlıyor!": "{A} maju dan menutup kombinasi pukulan dengan tendangan tubuh yang keras!",
  "{A} rakibini iplere dayayıp dirsekle tamamlanan bir kombinasyon indiriyor.": "{A} menekannya ke tali dan mendaratkan kombinasi yang diakhiri siku.",
  "{A} gövdeye tekme, kafaya kros: zincir hiç durmuyor!": "{A}: tendangan ke tubuh, cross ke kepala — rangkaiannya tak pernah berhenti!",
  "{A} gelen tekmeyi yakaladı ve kontra kros patlattı!": "{A} menangkap tendangan yang datang dan melepaskan counter cross!",
  "{B} tekmeye gidiyor ama {A} bloklayıp sert bir low kick ile cevap veriyor.": "{B} mengincar tendangan tapi {A} memblokir dan membalas dengan tendangan rendah keras.",
  "{A} geri adım atıyor, rakip boşluğa düşüyor ve dirsek yiyor.": "{A} mundur, lawan jatuh ke ruang kosong dan terkena siku.",
  "{A} teep ile mesafeyi koruyor, rakip içeri giremiyor.": "{A} menjaga jarak dengan teep; lawan tak bisa masuk.",
  "{A} uzun bir orta tekmeyle puan topluyor; gövde ses verdi.": "{A} mencetak poin dengan tendangan tubuh panjang; suaranya terdengar.",
  "{A} yüksek tekme fırlattı, gard son anda kalktı!": "{A} melempar tendangan tinggi, garda naik di detik terakhir!",
  "{A} plum klinç aldı, dizler gövdeye art arda iniyor!": "{A} mengunci plum clinch, lutut menghantam tubuh bertubi-tubi!",
  "{A} klinçten çıkarken kısa bir dirsek savuruyor, kaşın üstüne değdi!": "{A} melempar siku pendek saat lepas dari clinch; mengenai alis!",
  "{A} ensesinden çekip dizi yüze gönderdi!": "{A} menarik kepala ke bawah dan mengirim lutut ke wajah!",
  "{A} guard'ı geçip yan kontrole kuruldu, ağırlığını veriyor.": "{A} melewati guard dan duduk di side control, menaruh beratnya.",
  "{A} mount'a tırmandı! Rakip altta nefes almakta zorlanıyor.": "{A} naik ke mount! Lawan nyaris tak bisa bernapas di bawah.",
  "{A} sırtı aldı, iki kanca içeride. Kilit arıyor!": "{A} mengambil punggung, kedua kaitan terpasang. Memburu submission!",
  "{A} yarım guard'dan çıkıp diz-göbek pozisyonuna geçti.": "{A} lolos dari half guard dan pindah ke knee-on-belly.",
  "{A} rakibini çevirdi; sırtı mindere yaklaşıyor, puan!": "{A} membalik lawannya; punggungnya mendekati matras — poin!",
  "{A} yerde kontrolü aldı, rakibin omuzlarını mindere bastırıyor.": "{A} menguasai matras, menekan bahu lawannya ke bawah.",
  "{A} köprüdeki rakibini zorluyor; tuşa çok yakın!": "{A} mematahkan bridge lawannya — sangat dekat dengan kuncian bahu!",
  "{A} arkasına geçip rakibini yan çevirdi. İki puan!": "{A} masuk ke belakang dan membalik lawannya ke samping. Dua poin!",
  "{A} el kavgasını kazanıyor, bilekleri kontrol edip rakibini geri itiyor.": "{A} memenangkan adu tangan, mengendalikan pergelangan dan mendorong lawannya mundur.",
  "{A} kafa kafaya tutuşta baskı kuruyor; rakip mindere doğru geriliyor.": "{A} menekan dalam ikatan kepala-ke-kepala; lawan merosot ke arah matras.",
  "{A} bacaklara fint atıp rakibini dengesiz yakaladı.": "{A} pura-pura menyergap kaki dan menangkap lawannya kehilangan keseimbangan.",
  "{A} seviye değiştirip çift bacak dalıyor… ve rakibini mindere çarpıyor!": "{A} mengubah level, menyergap double-leg… dan membanting lawannya ke matras!",
  "{A} kalça atarak rakibini mindere savuruyor. Temiz fırlatma!": "{A} membanting lawannya dengan hip toss ke matras. Bantingan bersih!",
  "{A} tek bacağı yakaladı, rakibini döndürüp mindere indirdi.": "{A} menangkap single leg, memutar lawannya, dan membawanya ke matras.",
  "{A} bacağa dalıyor ama {B} sprawl ile savunuyor ve ayağa dönüyor.": "{A} menyergap kaki tapi {B} bertahan dengan sprawl dan bangkit lagi.",
  "{A} bacağa gidiyor, {B} kalçasını geri atıp dengesini koruyor. Boşa enerji.": "{A} mengincar kaki, {B} melempar pinggul ke belakang dan menjaga keseimbangan. Tenaga terbuang.",
  "{A} dalış yaptı ama {B} kafasını bastırıp girişi kesti.": "{A} menyergap tapi {B} menekan kepalanya ke bawah dan menghentikan sergapan.",
  "Sarıl, zaman kazan": "Bertahan, ulur waktu",
  "Rakibine sarıl, hakem ayırana kadar kafanı toparla.": "Ikat lawanmu dan jernihkan kepala sampai wasit memisahkan kalian.",
  "{0} köprü kurup döndü, tehlikeden çıktı!": "{0} melakukan bridge, berbalik, dan lolos dari bahaya!",
  "{0} belden kavrayıp rakibini mindere fırlattı!": "{0} mengunci pinggang dan membanting lawannya ke matras!",
  "{0} klinçte rakibini süpürüp mindere düşürdü! Puan.": "{0} menyapu lawannya di clinch dan menjatuhkannya ke kanvas! Poin.",
  "{0} riske girmiyor, üstte ağırlığını verip pozisyon puanı topluyor.": "{0} tak mengambil risiko, tetap di atas dengan berat ditekan dan mengumpulkan poin posisi.",
